function aiDeckCardScore(card,opponent){let score=Math.random()*8;if(opponent.attributes?.includes(card.attribute))score+=90;if(card.packIds?.some(id=>opponent.packs?.includes(id)))score+=80;if(card.tags?.some(tag=>opponent.tags?.includes(tag)))score+=60;if(opponent.strategyIds?.includes(card.id))score+=110;const rarity=RARITY_POWER[card.rarity]||1;score+=opponent.level==="hard"?rarity*12:opponent.level==="normal"?rarity*7:rarity*2;if(isVmaxCard(card))score+=opponent.allowVmax?45:-200;if(card.type==="strategy"&&!opponent.strategyIds?.includes(card.id))score+=opponent.level==="easy"?5:18;return score;}
function sortedAiCandidates(pool,deck,opponent){return pool.filter(card=>canDeckAcceptCard(deck,card)).map(card=>({card,score:aiDeckCardScore(card,opponent)})).sort((a,b)=>b.score-a.score).map(x=>x.card);}
function addAiCard(deck,pool,opponent){const picked=sortedAiCandidates(pool,deck,opponent)[0];if(!picked)return false;deck.push(picked.id);return true;}
function buildAiDeck(opponent=selectedAiOpponent()){const ai=opponent||AI_OPPONENTS[0],deck=[],characters=cards.filter(c=>c.type==="character"&&!isVmaxCard(c)),strategies=cards.filter(c=>c.type==="strategy");if(ai.allowVmax){const vmax=cards.filter(c=>c.type==="character"&&isVmaxCard(c)&&c.evolvesFrom).map(card=>({card,score:aiDeckCardScore(card,ai)})).sort((a,b)=>b.score-a.score).map(x=>x.card).find(card=>cardById[card.evolvesFrom]&&canDeckAcceptCard(deck,cardById[card.evolvesFrom])&&canDeckAcceptCard([...deck,card.evolvesFrom],card));if(vmax){deck.push(vmax.evolvesFrom,vmax.id);}}while(deckCounts(deck).characters<settings.characterLimit&&addAiCard(deck,characters,ai));while(deckCounts(deck).strategies<settings.strategyLimit&&addAiCard(deck,strategies,ai));if(!validDeck(deck)){const fallback=[];while(deckCounts(fallback).characters<settings.characterLimit&&addAiCard(fallback,characters,ai));while(deckCounts(fallback).strategies<settings.strategyLimit&&addAiCard(fallback,strategies,ai));return validDeck(fallback)?fallback:deck;}return deck;}
function pickRarity(){const odds=settings.rarityOdds||{};const total=Object.values(odds).reduce((sum,n)=>sum+n,0);let roll=Math.random()*total;for(const rarity of RARITIES){roll-=odds[rarity]||0;if(roll<=0)return rarity;}return RARITIES[RARITIES.length-1];}
function drawFromPack(pack){const pool=packCards(pack);if(!pool.length)return [];const available=new Set(pool.map(card=>card.rarity));return Array.from({length:settings.cardsPerPack||5},()=>{let wanted=pickRarity(),guard=0;while(!available.has(wanted)&&guard<100){wanted=pickRarity();guard++;}const pickedPool=pool.filter(card=>card.rarity===wanted);return pickedPool[Math.floor(Math.random()*pickedPool.length)]||pool[Math.floor(Math.random()*pool.length)];});}
function metricValue(metric){if(metric==="ownedCards")return cards.filter(c=>(profile.collection[c.id]||0)>0).length;if(metric==="ownedSSR")return cards.filter(c=>c.rarity==="SSR"&&(profile.collection[c.id]||0)>0).length;return profile.records?.[metric]||0;}
function awardAchievement(a){if(profile.achievements?.[a.id])return false;profile.achievements[a.id]=true;profile.currency+=(a.reward||0);save();pushNotification("도전과제 달성",`${a.title} · 보상 ${a.reward||0}P가 자동 지급되었습니다.`);return true;}
function checkAchievements(){achievements.forEach(a=>{if(!profile.achievements[a.id]&&metricValue(a.metric)>=a.target)awardAchievement(a);});}
function grantMatchReward(winner,{pvp=false}={}){if(!game||game.rewardClaimed||winner==null)return;const state=game.snapshot(),forfeit=state.pvpForfeit,userId=currentUser()?.id,forfeited=pvp&&forfeit?.loserUserId===userId,claimKey=pvp&&pvpSession?.matchId?`${userId||"guest"}:${pvpSession.matchId}`:null;if(claimKey&&profile.claimedPvpMatches?.[claimKey]){game.rewardClaimed=true;return;}const won=winner===0,rewardKey=pvp?(won?"pvpWin":"pvpLoss"):(won?"aiWin":"aiLoss"),legacyKey=won?"win":"loss",reward=forfeited?0:(settings.reward?.[rewardKey]??settings.reward?.[legacyKey]??0),penalty=Math.max(0,Number(forfeit?.penalty??settings.reward?.pvpForfeitPenalty??30)),deducted=forfeited?Math.min(Math.max(0,Number(profile.currency)||0),penalty):0;game.rewardClaimed=true;profile.claimedPvpMatches=profile.claimedPvpMatches||{};if(claimKey)profile.claimedPvpMatches[claimKey]=true;profile.records.plays=(profile.records.plays||0)+1;profile.records[pvp?"pvpPlays":"aiPlays"]=(profile.records[pvp?"pvpPlays":"aiPlays"]||0)+1;if(won){profile.records.wins=(profile.records.wins||0)+1;profile.records[pvp?"pvpWins":"aiWins"]=(profile.records[pvp?"pvpWins":"aiWins"]||0)+1;}else profile.records.losses=(profile.records.losses||0)+1;profile.currency=forfeited?Math.max(0,(Number(profile.currency)||0)-deducted):(Number(profile.currency)||0)+reward;save();checkAchievements();notify(forfeited?`탈주 패배 · 페널티 -${deducted}P (보유 포인트 ${profile.currency}P)`: `${won?"승리":"패배"} 보상 +${reward}P · ${pvp?"PvP":"AI 대전"}`);}
function matchRewardText(state,pvp){const forfeit=state?.pvpForfeit;if(pvp&&forfeit?.loserUserId===currentUser()?.id)return `탈주 페널티 최대 ${Math.max(0,Number(forfeit.penalty??settings.reward?.pvpForfeitPenalty??30))}P가 차감되었습니다.`;const won=state?.winner===0,rewardKey=pvp?(won?"pvpWin":"pvpLoss"):(won?"aiWin":"aiLoss"),legacyKey=won?"win":"loss";return `${settings.reward?.[rewardKey]??settings.reward?.[legacyKey]??0}P 보상이 지급되었습니다.`;}
let audioContext = null;
let visualEffectQueue = Promise.resolve();
let visualEffectGeneration = 0;
let musicTracks = {};
let currentMusicKey = null;
let musicFadeTimer = null;
const AUDIO_PREF_KEY = "politimon-audio-prefs-v1";
const UI_PREF_KEY = "politimon-ui-prefs-v1";
