const loadAudioPrefs = () => { try { return { music:true, effects:true, volume:70, ...JSON.parse(localStorage.getItem(AUDIO_PREF_KEY)||"{}") }; } catch { return { music:true, effects:true, volume:70 }; } };
let audioPrefs = loadAudioPrefs();
