function applyUiPrefs(){document.documentElement.dataset.theme="dark";document.body.classList.toggle("reduce-motion",!!uiPrefs.reducedMotion);document.body.classList.toggle("compact-cards",!!uiPrefs.compactCards);}

function unlockAudio(){const AudioCtor=window.AudioContext||window.webkitAudioContext;if(!AudioCtor)return;audioContext=audioContext||new AudioCtor();if(audioContext.state==="suspended")audioContext.resume().catch(()=>{});}
function tone(freq,start,duration,{type="sine",gain=.08,endFreq=null}={}){if(!audioPrefs.effects)return;unlockAudio();if(!audioContext||audioContext.state!=="running")return;const osc=audioContext.createOscillator(),amp=audioContext.createGain(),now=audioContext.currentTime+start;osc.type=type;osc.frequency.setValueAtTime(freq,now);if(endFreq)osc.frequency.exponentialRampToValueAtTime(endFreq,now+duration);amp.gain.setValueAtTime(.0001,now);amp.gain.exponentialRampToValueAtTime(gain,now+.012);amp.gain.exponentialRampToValueAtTime(.0001,now+duration);osc.connect(amp).connect(audioContext.destination);osc.start(now);osc.stop(now+duration+.02);}
function playImpactSound(){if(!audioPrefs.effects)return;tone(115,0,.18,{type:"square",gain:.2,endFreq:48});tone(230,.025,.11,{type:"sawtooth",gain:.08,endFreq:80});tone(920,.015,.05,{type:"triangle",gain:.055,endFreq:420});}
function playCastSound(kind="skill"){if(!audioPrefs.effects)return;if(kind==="trait"){tone(280,0,.16,{type:"sine",gain:.07,endFreq:430});tone(520,.08,.18,{type:"triangle",gain:.045,endFreq:720});return;}tone(360,0,.12,{type:"triangle",gain:.07,endFreq:620});tone(740,.07,.16,{type:"sawtooth",gain:.05,endFreq:980});}
function playCoinSound(){if(!audioPrefs.effects)return;[0,.09,.18,.31].forEach((offset,i)=>tone(760-(i*95),offset,.08,{type:"triangle",gain:.08}));}
function playPackSound(){if(!audioPrefs.effects)return;[220,330,440,660,880].forEach((freq,i)=>tone(freq,i*.08,.16,{type:i<3?"sawtooth":"triangle",gain:.09}));}
function musicTargetVolume(key){return (key==="battle" ? .28 : .22)*(Number(audioPrefs.volume||0)/70);}
function ensureMusic(key){if(musicTracks[key])return musicTracks[key];const src=key==="battle"?"assets/bgm.mp3":"assets/home.mp3",audio=new Audio(src);audio.loop=true;audio.volume=0;audio.addEventListener("error",()=>{}, {once:true});musicTracks[key]=audio;return audio;}
function fadeInAudio(audio,target=.25,duration=1800){clearInterval(musicFadeTimer);audio.volume=0;const started=Date.now();musicFadeTimer=setInterval(()=>{const t=Math.min(1,(Date.now()-started)/duration);audio.volume=target*t;if(t>=1)clearInterval(musicFadeTimer);},60);}
function stopMusic(){clearInterval(musicFadeTimer);Object.values(musicTracks).forEach(audio=>{audio.pause();audio.currentTime=0;audio.volume=0;});currentMusicKey=null;}
function switchMusic(key,{restart=false}={}){if(!audioPrefs.music){stopMusic();return;}if(currentMusicKey===key&&!restart)return;Object.entries(musicTracks).forEach(([trackKey,audio])=>{if(trackKey!==key){audio.pause();audio.currentTime=0;audio.volume=0;}});const audio=ensureMusic(key);currentMusicKey=key;if(restart)audio.currentTime=0;audio.play().then(()=>fadeInAudio(audio,musicTargetVolume(key),1900)).catch(()=>{});}
function syncRouteMusic({restart=false}={}){switchMusic(route==="game"?"battle":"home",{restart});}
function updateAudioControls(){document.querySelectorAll("#top-toggle-music,#toggle-music").forEach(el=>{el.classList.toggle("on",audioPrefs.music);if(el.id==="top-toggle-music")el.textContent=`음악 ${audioPrefs.music?"ON":"OFF"}`;});document.querySelectorAll("#top-toggle-effects,#toggle-effects").forEach(el=>{el.classList.toggle("on",audioPrefs.effects);if(el.id==="top-toggle-effects")el.textContent=`효과 ${audioPrefs.effects?"ON":"OFF"}`;});}
function setAudioPref(key,value){audioPrefs[key]=value;saveAudioPrefs();if(key==="music"){if(value)syncRouteMusic({restart:true});else stopMusic();}updateAudioControls();}
function clearBattleEffects(){visualEffectGeneration++;visualEffectQueue=Promise.resolve();document.querySelectorAll(".action-veil,.damage-burst,.hit-effect,.damage-tag,.coin-flip-overlay,.pack-open-overlay,.ai-choice-veil,.turn-transition").forEach(el=>el.remove());document.body.classList.remove("impact-shake");document.querySelectorAll(".battle-card").forEach(el=>el.classList.remove("hit","cast-pulse","levitate-cast","attack-lunge","attack-lunge-back"));}
function enqueueVisualEffect(run,fallbackValue=undefined){if(!audioPrefs.effects)return Promise.resolve(fallbackValue);const generation=visualEffectGeneration,next=visualEffectQueue.then(()=>new Promise(resolve=>{if(generation!==visualEffectGeneration){resolve(fallbackValue);return;}run(value=>resolve(value===undefined?fallbackValue:value));}));visualEffectQueue=next.catch(()=>{});return next;}
function playHitEffect(detail){enqueueVisualEffect(resolve=>{const target=detail?.target===0?"player":"enemy",source=detail?.source===0?"player":"enemy",zone=document.querySelector(target==="player"?".player-zone .battle-card":".opponent-zone .battle-card"),attacker=document.querySelector(source==="player"?".player-zone .battle-card":".opponent-zone .battle-card"),modifiers=detail?.modifiers||[],damage=Number(detail?.damage)||0,base=Number(detail?.baseDamage)||damage,changed=base!==damage||modifiers.length>0;if(attacker){attacker.classList.remove("attack-lunge","attack-lunge-back");void attacker.offsetWidth;attacker.classList.add(source==="player"?"attack-lunge":"attack-lunge-back");setTimeout(()=>attacker.classList.remove("attack-lunge","attack-lunge-back"),EFFECT_DURATION_MS);}document.body.classList.remove("impact-shake");void document.body.offsetWidth;document.body.classList.add("impact-shake");setTimeout(()=>document.body.classList.remove("impact-shake"),EFFECT_DURATION_MS);const burst=document.createElement("div"),burstText=document.createElement("b"),burstMeta=document.createElement("span");burst.className=`damage-burst ${changed?"modified":""}`;burstText.textContent=damage?`${damage} DAMAGE`:"HIT";burstMeta.textContent=modifiers.length?modifiers.join(" · "):(detail?.direct?"직접 피해":"타격");burst.append(burstText,burstMeta);document.body.append(burst);if(zone){zone.classList.remove("hit");void zone.offsetWidth;zone.classList.add("hit");const ring=document.createElement("i"),tag=document.createElement("b"),meta=document.createElement("em");ring.className="hit-effect";tag.className=`damage-tag ${changed?"modified":""}`;tag.textContent=damage?`-${damage}`:"HIT";meta.textContent=modifiers.join(" · ");zone.append(ring,tag);if(modifiers.length)zone.append(meta);setTimeout(()=>{ring.remove();tag.remove();meta.remove();zone.classList.remove("hit");},EFFECT_DURATION_MS);}playImpactSound();setTimeout(()=>burst.remove(),EFFECT_DURATION_MS);setTimeout(resolve,EFFECT_DURATION_MS);});}
function showActionEffect({source=0,type="skill",label="",color="#70efff",cardId=""}={}){enqueueVisualEffect(resolve=>{const effectColor=type==="trait"?"#ff667f":type==="strategy"?"#ffb45b":color,zone=document.querySelector(source===0?".player-zone .battle-card":".opponent-zone .battle-card"),levitates=type==="trait"&&cardId==="character_55";if(zone){zone.style.setProperty("--effect-color",effectColor);zone.classList.remove("cast-pulse","levitate-cast");void zone.offsetWidth;zone.classList.add(levitates?"levitate-cast":"cast-pulse");setTimeout(()=>zone.classList.remove("cast-pulse","levitate-cast"),EFFECT_DURATION_MS);}const veil=document.createElement("div"),text=document.createElement("b"),small=document.createElement("span");veil.className=`action-veil ${type} ${levitates?"levitate":""}`;veil.style.setProperty("--effect-color",effectColor);small.textContent=type==="trait"?"TRAIT":type==="strategy"?"STRATEGY":"SKILL";text.append(small,document.createTextNode(label));veil.append(text);document.body.append(veil);playCastSound(type);setTimeout(()=>veil.remove(),EFFECT_DURATION_MS);setTimeout(resolve,EFFECT_DURATION_MS);});}
function showTurnTransition(playerIndex){return enqueueVisualEffect(resolve=>{document.querySelectorAll(".turn-transition").forEach(x=>x.remove());const veil=document.createElement("div"),label=document.createElement("b"),caption=document.createElement("span");veil.className="turn-transition";caption.textContent="TURN CHANGE";label.append(caption,document.createTextNode(playerIndex===0?"나의 턴":"상대의 턴"));veil.append(label);document.body.append(veil);setTimeout(()=>{veil.remove();resolve();},EFFECT_DURATION_MS);});}
function hasCoinFlipText(text=""){return /동전|코인|coin/i.test(text);}
const decideCoinFace=forced=>forced==="heads"||forced==="tails"?forced:(Math.random()<.5?"heads":"tails");
function showCoinFlip({caption="COIN FLIP",headsLabel="앞",tailsLabel="뒤",result:requestedResult}={}){const result=decideCoinFace(requestedResult);return enqueueVisualEffect(resolve=>{document.querySelectorAll(".coin-flip-overlay").forEach(x=>x.remove());const overlay=document.createElement("div"),panel=document.createElement("div"),coin=document.createElement("div"),front=document.createElement("span"),back=document.createElement("span"),engraving=document.createElement("img"),title=document.createElement("b"),sub=document.createElement("p"),isHeads=result==="heads",isTurnOrder=/선공/.test(headsLabel)&&/선공/.test(tailsLabel);overlay.className="coin-flip-overlay";panel.className="coin-flip-panel";coin.className=`coin-flip coin-motion-${isHeads?"heads":"tails"}`;front.className="coin-heads";back.className="coin-tails";engraving.className="coin-engraving";engraving.src="assets/coin-politimon-engraving.png";engraving.alt="";front.append(engraving);title.textContent=caption;sub.textContent="동전이 공중에서 회전합니다";coin.append(front,back);panel.append(title,coin,sub);overlay.append(panel);document.body.append(overlay);playCoinSound();setTimeout(()=>{sub.textContent=`결과: ${isTurnOrder?(isHeads?headsLabel:tailsLabel):(isHeads?"앞":"뒤")}`;panel.classList.add("resolved");},1250);setTimeout(()=>{overlay.remove();resolve(result);},EFFECT_DURATION_MS);},result);}
