function showPackOpening(pack){return new Promise(resolve=>{if(!audioPrefs.effects){resolve();return;}document.querySelectorAll(".pack-open-overlay").forEach(x=>x.remove());const overlay=document.createElement("div");overlay.className="pack-open-overlay";overlay.innerHTML=`<div class="pack-open-panel"><div class="pack-burst"></div><div class="pack-foil"><span>POLITIMON</span><b>${escape(pack.name)}</b></div><p>카드팩을 개봉하는 중...</p></div>`;document.body.append(overlay);playPackSound();setTimeout(()=>overlay.classList.add("opened"),900);setTimeout(()=>{overlay.remove();resolve();},EFFECT_DURATION_MS);});}

function notify(message){const el=document.querySelector("#toast");el.textContent=message;el.classList.add("show");clearTimeout(notify.timer);notify.timer=setTimeout(()=>el.classList.remove("show"),2700);}
function go(next,{remember=true}={}){if(next===route)return;if(roomNavigationLocked()&&next!=="game"&&next!=="multiplayer"){notify("방에 참가 중입니다. 나가려면 방 나가기 버튼을 사용하세요.");return;}if(remember&&route!=="game")previousRoute=route;if(route==="game"&&next!=="game"){const shouldLeaveFinishedRoom=isPvpMatch()&&game?.snapshot?.().phase==="finished"&&!!activeRoom;clearBattleEffects();if(shouldLeaveFinishedRoom)leaveActiveRoom();game=null;stopPvpWatch();}if(route==="multiplayer"&&next!=="multiplayer"&&activeRoom)leaveActiveRoom();if(next==="gallery")galleryLoaded=false;route=next;if(location.hash.slice(1)!==next)location.hash=next;else render();}
function goBack(){go(previousRoute&&previousRoute!==route?previousRoute:"home",{remember:false});}
function cardArt(card, small=false){return `<article class="card ${card.type} ${small?"small":""}" data-card="${card.id}"><div class="card-top"><span class="rarity r-${card.rarity.replace(/[^a-zA-Z]/g,"")}">${card.rarity}</span><span>${typeLabel(card.type)}</span></div><img src="${cardImage(card)}" alt="${escape(card.name)}" data-ext="png" onerror="nextCardImage(this,'${escape(card.id)}')"><div class="missing-art">IMAGE<br>NOT FOUND</div><div class="card-bottom"><h3>${escape(card.name)}</h3>${card.type==="character"?`<div><span>${escape(attributeLabel(card.attribute))}</span><b>HP ${card.hp}</b></div>`:`<div><span>전략</span><b>${escape(card.rarity)}</b></div>`}</div></article>`;}
function icon(name){return `<span class="nav-icon">${name}</span>`}

