function homeNews(){const news=window.POLITIMON_HOME_NEWS||{image:"assets/news/news-01.jpg",label:"POLITIMON NEWS",title:"정켓몬스터 카드 게임 베타",description:"카드 수집과 AI 대전을 지금 시작해 보세요."};return `<aside class="news-board home-featured-news"><img src="${escape(news.image)}" alt="${escape(news.title)}" onerror="this.style.display='none'"><div class="home-news-fallback"><span>${escape(news.label)}</span><b>${escape(news.title)}</b><small>${escape(news.description)}</small></div><div class="home-news-copy"><small>${escape(news.label)}</small><b>${escape(news.title)}</b><p>${escape(news.description)}</p></div></aside>`;}
const currentUser=()=>authSession?.user||null;
const displayName=user=>user?.user_metadata?.display_name||user?.email?.split("@")[0]||"게스트";
function accountEmail(username){const id=String(username||"").trim().toLowerCase();if(id.includes("@"))return id;if(!/^[a-z0-9_-]{3,20}$/.test(id))throw new Error("아이디는 영문·숫자·밑줄·하이픈 3~20자로 입력해 주세요.");return `${id}@player.politimon.game`;}
function updateHeaderUser(){const user=currentUser(),name=document.querySelector("#profile-name"),status=document.querySelector("#profile-status"),avatar=document.querySelector("#profile-avatar");if(name)name.textContent=displayName(user);if(status)status.textContent=user?(isDeveloper?"DEV TEST":window.politimonBackend?.configured?"ONLINE":"PREVIEW") : "GUEST";if(avatar)avatar.textContent=(displayName(user)[0]||"P").toUpperCase();}
async function syncDeveloperAccess(){const user=currentUser();if(!user){isDeveloper=false;return false;}try{const account=await window.politimonBackend.getDeveloperProfile(user.id),next=!!account.is_developer,becameDeveloper=next&&!isDeveloper;isDeveloper=next;if(next){profile.currency=Math.max(profile.currency||0,10000);profile.collection=Object.fromEntries(cards.map(card=>[card.id,1]));profile.deck=(profile.deck||[]).filter(id=>cardById[id]);save();checkAchievements();if(becameDeveloper)notify("개발 테스트 계정 권한이 적용되었습니다.");}return next;}catch(error){isDeveloper=false;notify(`개발자 권한을 확인하지 못했습니다: ${error.message}`);return false;}}
function needLogin(){if(currentUser())return true;notify("로그인 후 이용할 수 있습니다.");go("auth");return false;}
async function loadGalleryPosts(){if(galleryLoading)return;galleryLoading=true;try{galleryPosts=await window.politimonBackend.listPosts();galleryLoaded=true;if(!selectedGalleryPostId&&galleryPosts[0])selectedGalleryPostId=galleryPosts[0].id;}catch(error){notify(`갤러리를 불러오지 못했습니다: ${error.message}`);}finally{galleryLoading=false;if(route==="gallery")render();}}
function renderGalleryModerationButton(){const post=galleryPosts.find(item=>item.id===selectedGalleryPostId)||galleryPosts[0],reading=document.querySelector(".gallery-reading"),meta=reading?.querySelector(".post-meta"),canDelete=isDeveloper||post?.author_id===currentUser()?.id;if(!canDelete||route!=="gallery"||!post||!meta||meta.querySelector("[data-delete-gallery-post]"))return;const button=document.createElement("button");button.type="button";button.className="btn ghost gallery-delete";button.dataset.deleteGalleryPost=post.id;button.textContent="글 삭제";meta.append(button);}
function roomListSignature(rooms=[]){return rooms.map(room=>`${room.id}|${room.title}|${room.is_private}|${room.owner_name||""}|${room.player_count??room.members?.length??0}|${room.status||"waiting"}`).join("\n");}
function renderLobbyRefreshButton(){const title=document.querySelector(".lobby-title"),leave=title?.querySelector("#leave-room");if(route!=="multiplayer"||!activeRoom||!leave||title.querySelector("#refresh-active-room"))return;const button=document.createElement("button");button.type="button";button.className="btn ghost";button.id="refresh-active-room";button.textContent="↻ 상대 입장 확인";leave.insertAdjacentElement("beforebegin",button);}
async function loadRooms({force=false}={}){if(roomsLoading||(!force&&roomsLoaded))return;const wasLoaded=roomsLoaded,previousSignature=roomListSignature(multiplayerRooms);roomsLoading=true;let changed=false;try{const nextRooms=await window.politimonBackend.listRooms();changed=roomListSignature(nextRooms)!==previousSignature;if(changed)multiplayerRooms=nextRooms;roomsLoaded=true;}catch(error){notify(`방 목록을 불러오지 못했습니다: ${error.message}`);}finally{roomsLoading=false;if(route==="multiplayer"&&(!wasLoaded||changed))render();}}
async function refreshActiveRoom(){if(!activeRoom?.id)return;try{const next=await window.politimonBackend.getRoom(activeRoom.id);if(!next)throw new Error("방을 찾을 수 없습니다.");activeRoom=next;if(next.status==="playing"){const match=await window.politimonBackend.getMatch(next.id);if(adoptPvpMatch(match))return;}render();notify("방 상태를 새로고침했습니다.");}catch(error){notify(`방 상태를 불러오지 못했습니다: ${error.message}`);}}
async function leaveActiveRoom({serverAlreadyLeft=false,notifyOnSuccess=true}={}){const room=activeRoom,roomId=room?.id;if(!roomId||leavingRoom)return false;leavingRoom=true;activeRoom=null;stopPvpWatch();if(route==="game")game=null;render();try{if(!serverAlreadyLeft)await window.politimonBackend.leaveRoom(roomId,currentUser());roomsLoaded=false;await loadRooms({force:true});if(notifyOnSuccess)notify("방에서 나왔습니다.");return true;}catch(error){activeRoom=room;notify(`방에서 나가지 못했습니다: ${error.message}`);render();return false;}finally{leavingRoom=false;}}
async function forfeitPvpMatch(){const state=game?.snapshot?.(),session=pvpSession;if(!session||session.pending||leavingRoom||state?.phase==="finished")return false;const penalty=Math.max(0,Number(settings.reward?.pvpForfeitPenalty??30));if(!confirm(`지금 방을 나가면 탈주 패배로 처리되고 최대 ${penalty}P가 차감됩니다.\n상대방은 승리로 처리되어 승리 포인트를 받습니다.\n\n그래도 방을 나가시겠습니까?`))return false;session.pending=true;render();try{const match=await window.politimonBackend.forfeitMatch(session.matchId,session.version);if(!adoptPvpMatch(match,{navigate:false}))throw new Error("탈주 결과를 불러오지 못했습니다.");await leaveActiveRoom({serverAlreadyLeft:true,notifyOnSuccess:false});go("home");return true;}catch(error){if(pvpSession)pvpSession.pending=false;notify(`탈주 처리에 실패했습니다: ${error.message}`);render();return false;}}
function home(){const owned=cards.filter(c=>(profile.collection[c.id]||0)>0).length,achievementCount=Object.keys(profile.achievements||{}).length;return `<section class="home-screen home-metro"><div class="home-main"><div class="home-menu"><p class="home-intro">카드를 모아 나만의 덱을 만들고, 컨셉별 AI와 전략 대결을 시작하세요.</p><div class="primary-menu"><button class="metro-menu primary" data-route="ai"><span>♙</span><div><b>싱글 플레이</b><small>컨셉과 난이도를 골라 AI 대전을 시작합니다</small></div><i>→</i></button><button class="metro-menu" data-route="multiplayer"><span>♧</span><div><b>멀티 플레이</b><small>방을 만들고 친구와 실시간 대전을 준비합니다</small></div><i>→</i></button><button class="metro-menu" data-route="packs"><span>✦</span><div><b>카드 팩 센터</b><small>새 카드로 컬렉션과 덱을 확장하세요</small></div><i>→</i></button></div><div class="utility-menu"><button data-route="achievements">◎ 도전과제 <small>${achievementCount}/${achievements.length}</small></button><button data-route="collection">▦ 도감</button><button data-route="gallery">▧ 갤러리</button><button data-route="guide">? 이용 안내</button><button data-route="patch">✦ 패치 노트</button><button data-route="deck">▤ 덱 짜기</button></div></div>${homeNews()}</div><div class="home-status"><span><b>${owned}</b> / ${cards.length} 카드 보유</span><span><b>${profile.deck.length}</b> / ${settings.deckCardCount} 덱 구성</span><span><b>${profile.records.wins||0}</b> 승</span></div></section>`;}
function authView(){const user=currentUser();if(user)return `<section class="page auth-page"><div class="section-back"><button data-route="home">← 홈으로</button><span>계정</span></div><div class="auth-card"><p class="eyebrow">ACCOUNT</p><h2>${escape(displayName(user))}님, 접속 중입니다</h2><p>아이디 ${escape(displayName(user))} · ${window.politimonBackend?.configured?"Supabase 계정이 연결되었습니다.":"이 브라우저의 미리보기 계정입니다. 배포 전 Supabase 연결값을 입력하세요."}</p><button class="btn primary" id="signout">로그아웃</button></div></section>`;return `<section class="page auth-page"><div class="section-back"><button data-route="home">← 홈으로</button><span>로그인</span></div><div class="auth-layout"><form class="auth-card" id="simple-signin-form"><p class="eyebrow">SIGN IN</p><h2>로그인</h2><label>아이디<input name="username" required minlength="3" maxlength="20" pattern="[A-Za-z0-9_-]{3,20}" autocomplete="username" placeholder="영문, 숫자, _, -"></label><label>비밀번호<input name="password" type="password" required minlength="6" autocomplete="current-password" placeholder="6자 이상"></label><button class="btn primary">바로 플레이</button></form><form class="auth-card" id="simple-signup-form"><p class="eyebrow">NEW TRAINER</p><h2>회원가입</h2><label>아이디<input name="username" required minlength="3" maxlength="20" pattern="[A-Za-z0-9_-]{3,20}" autocomplete="username" placeholder="영문, 숫자, _, -"></label><label>비밀번호<input name="password" type="password" required minlength="6" autocomplete="new-password" placeholder="6자 이상"></label><button class="btn secondary">계정 만들고 바로 플레이</button><small>이메일 입력과 별도 인증 없이 시작합니다.</small></form></div></section>`;}
function renderAccountDeletionButton(){const signout=document.querySelector("#signout");if(route!=="auth"||!currentUser()||!signout||document.querySelector("#delete-account"))return;const button=document.createElement("button");button.type="button";button.className="btn ghost";button.id="delete-account";button.textContent="회원 탈퇴";signout.insertAdjacentElement("afterend",button);}
function galleryView(){const selected=galleryPosts.find(post=>post.id===selectedGalleryPostId)||galleryPosts[0];return `<section class="page gallery-page"><div class="section-back"><button data-route="home">← 홈으로</button><span>갤러리</span></div><div class="gallery-head"><div><p class="eyebrow">POLITIMON GALLERY</p><h2>정치몬 갤러리</h2><p>제목을 눌러 글을 읽고, 로그인 후 새 글을 작성할 수 있습니다.</p></div><button class="btn primary" id="gallery-write">✎ 글쓰기</button></div><div class="gallery-board"><section class="gallery-list"><div class="gallery-columns"><span>번호</span><span>제목</span><span>글쓴이</span><span>작성일</span></div>${galleryLoading?`<p class="gallery-empty">글 목록을 불러오는 중입니다…</p>`:galleryPosts.length?galleryPosts.map((post,index)=>`<button class="gallery-row ${post.id===selected?.id?"selected":""}" data-gallery-post="${post.id}"><span>${galleryPosts.length-index}</span><b>${escape(post.title)}</b><em>${escape(post.author||post.profiles?.display_name||"익명")}</em><small>${new Date(post.created_at).toLocaleDateString("ko-KR")}</small></button>`).join(""):`<p class="gallery-empty">아직 작성된 글이 없습니다. 첫 글을 남겨 보세요.</p>`}</section><article class="gallery-reading">${selected?`<div class="post-meta"><span>NO. ${galleryPosts.length-galleryPosts.indexOf(selected)}</span><span>${escape(selected.author||selected.profiles?.display_name||"익명")} · ${new Date(selected.created_at).toLocaleString("ko-KR")}</span></div><h3>${escape(selected.title)}</h3><p>${escape(selected.body).replace(/\n/g,"<br>")}</p>`:`<div class="gallery-empty">왼쪽 목록에서 글을 선택하세요.</div>`}</article></div></section>`;}
function roomMembers(room){return (room?.members||[]).map(member=>`<article class="room-member ${member.ready&&member.deck_ready?"ready":""}"><span>${member.is_host?"♛":"♙"}</span><div><b>${escape(member.display_name||member.name||"플레이어")}</b><small>${member.is_host?"방장":"참가자"} · ${member.deck_ready?"덱 등록":"덱 미등록"}</small></div><em>${member.ready&&member.deck_ready?"준비 완료":"준비 중"}</em></article>`).join("");}
function multiplayerView(){const user=currentUser();if(activeRoom){const mine=activeRoom.members?.find(member=>member.user_id===user?.id),isHost=activeRoom.owner_id===user?.id||mine?.is_host,allReady=activeRoom.members?.length===2&&activeRoom.members.every(member=>member.ready&&member.deck_ready);return `<section class="page multiplayer-page"><div class="lobby-room"><div class="lobby-title"><div><p class="eyebrow">MATCH LOBBY</p><h2>${escape(activeRoom.title)}</h2><p>${activeRoom.is_private?"🔒 비공개 방":"🌐 공개 방"} · ${activeRoom.members?.length||0}/2명</p></div><button class="btn ghost" id="leave-room">방 나가기</button></div><div class="room-members">${roomMembers(activeRoom)}${(activeRoom.members?.length||0)<2?`<article class="room-member vacant"><span>＋</span><div><b>상대를 기다리는 중</b><small>친구에게 방 제목을 알려 주세요</small></div></article>`:""}</div><div class="lobby-actions">${isHost?`<p>두 명 모두 준비하고 현재 덱을 등록하면 실시간 전투를 시작할 수 있습니다.</p><button class="btn primary" id="room-start" ${allReady?"":"disabled"}>PvP 시작 →</button>`:`<p>준비를 누르면 내 10장 덱이 등록됩니다. 방장이 시작할 때까지 기다리세요.</p><button class="btn primary" id="room-ready">${mine?.ready?"준비 취소":"준비"}</button>`}</div><small class="backend-note">${window.politimonBackend?.configured?"카드·HP·손패·토큰·덱 순서는 Supabase Realtime으로 동기화됩니다.":"Supabase 연결을 마치면 다른 기기와 실시간 PvP를 할 수 있습니다."}</small></div></section>`;}
return `<section class="page multiplayer-page"><div class="section-back"><button data-route="home">← 홈으로</button><span>멀티 플레이</span></div><div class="multiplayer-head"><div><p class="eyebrow">MULTIPLAYER</p><h2>멀티 플레이</h2><p>공개 방을 바로 입장하거나, 비공개 4자리 비밀번호 방을 만들어 친구를 초대하세요.</p></div><button class="btn primary" id="create-room">＋ 방 만들기</button></div><div class="room-filters"><span>대기 중인 방</span><button class="btn ghost" id="refresh-rooms">↻ 새로고침</button></div><div class="room-list">${roomsLoading?`<p class="gallery-empty">방 목록을 불러오는 중입니다…</p>`:multiplayerRooms.length?multiplayerRooms.map(room=>`<article class="room-card"><div class="room-lock">${room.is_private?"🔒":"🌐"}</div><div><small>${room.is_private?"비공개 방":"공개 방"}</small><h3>${escape(room.title)}</h3><p>방장 ${escape(room.owner_name||"플레이어")} · ${room.player_count??room.members?.length??1}/2명</p></div><button class="btn primary" data-join-room="${room.id}">${room.is_private?"비밀번호 입력":"입장"} →</button></article>`).join(""):`<p class="gallery-empty">아직 대기 중인 방이 없습니다. 첫 방을 만들어 보세요.</p>`}</div><small class="backend-note">${user?"입장 후 참가자는 준비, 방장은 시작 버튼을 사용합니다.":"방 만들기와 입장은 로그인 후 사용할 수 있습니다."}</small></section>`;}
function aiSelect(){const selected=selectedAiOpponent(),deckState=deckCounts(profile.deck),deckReady=profile.deck.length===settings.deckCardCount;return `<section class="page ai-select-page"><div class="section-back"><button data-route="home">← 홈으로</button><span>AI 대전</span></div><div class="ai-selection-head"><div><p class="eyebrow">SINGLE PLAY</p><h2><span>♙</span> AI 대전</h2><p>난이도가 높을수록 강한 희귀도 카드와 VMAX를 활용합니다. 내 덱을 점검하고 상대의 컨셉에 맞춰 전략을 준비하세요.</p></div><button class="ai-deck-shortcut" data-route="deck"><i>▤</i><span><b>덱 편집</b><small>${deckState.characters}/${settings.characterLimit} 인물 · ${deckState.strategies}/${settings.strategyLimit} 전략</small></span><em>→</em></button></div><div class="ai-selection-grid"><div class="ai-roster">${AI_OPPONENTS.map(ai=>`<button class="ai-match-card ${ai.id===selected.id?"active":""}" data-ai-opponent="${ai.id}"><span class="difficulty ${ai.level}">${escape(ai.difficulty)}</span><b>${escape(ai.name)}</b><small>${escape(ai.concept)}</small><div>${ai.attributes.map(a=>`<i style="--token-color:${tokenColor(a)}"></i>`).join("")}</div></button>`).join("")}</div><aside class="ai-opponent-preview"><p class="eyebrow">OPPONENT BRIEF</p><span class="difficulty ${selected.level}">${escape(selected.difficulty)}</span><h3>${escape(selected.name)}</h3><p>${escape(selected.concept)} 컨셉의 AI입니다. 토큰 색과 약점·저항을 확인해 유리한 교체와 기술 사용 순서를 만드세요.</p><div class="ai-preview-tokens">${selected.attributes.map(a=>`<span><i style="--token-color:${tokenColor(a)}"></i>${escape(attributeLabel(a))}</span>`).join("")}</div><div class="ai-ready-note ${deckReady?"ready":""}"><b>${deckReady?"덱 준비 완료":"덱 편성이 필요합니다"}</b><small>${deckReady?"바로 대전을 시작할 수 있습니다.":`총 ${settings.deckCardCount}장이 되도록 덱을 구성해 주세요.`}</small></div></aside></div><footer class="ai-launch"><div><small>선택한 상대</small><b>${escape(selected.name)} · ${escape(selected.difficulty)}</b></div><button class="btn primary" data-start-ai="${selected.id}">대전 시작 <b>→</b></button></footer></section>`;}
function guideView(){const basics=[`<article><b>1. 카드 팩 센터</b><p>카드 팩 센터에서 재화를 사용해 카드를 획득합니다. 보유한 카드는 도감에서 한눈에 확인할 수 있습니다.</p></article>`,`<article><b>2. 덱 만들기</b><p>덱은 인물 ${settings.characterLimit}장과 전략 ${settings.strategyLimit}장, 총 ${settings.deckCardCount}장입니다. SSR과 VMAX에는 편성 제한이 있습니다.</p></article>`,`<article><b>3. AI 상대 선택</b><p>싱글 플레이에서 컨셉과 난이도를 고른 뒤 대전을 시작합니다. 덱이 완성되지 않았다면 덱 편집 화면으로 안내됩니다.</p></article>`,`<article><b>4. 도감과 도전과제</b><p>도감에서는 보유 카드와 카드 정보를 볼 수 있고, 도전과제 보상은 조건 달성 즉시 자동 지급됩니다. 획득 내역은 상단 알림에서 확인하세요.</p></article>`];const battle=[`<article><b>1. 게임 시작과 선공</b><p>양쪽은 준비된 덱에서 카드를 뽑아 시작합니다. 선공은 첫 턴에 공격 제약이 있을 수 있으니, 화면의 턴 안내와 행동 가능 표시를 먼저 확인하세요.</p></article>`,`<article><b>2. 배틀 필드와 벤치</b><p>배틀 필드의 인물이 전투를 담당합니다. 손패의 인물은 벤치에 준비할 수 있으며, 현재 배틀 인물이 쓰러지면 준비된 인물 중 하나를 새 배틀 인물로 선택합니다.</p></article>`,`<article><b>3. 카드와 행동 순서</b><p>내 턴에는 카드의 특성, 기술, 진화, 후퇴와 전략 카드를 가능한 범위에서 사용합니다. 각 카드와 버튼을 눌러 효과·대상·비용을 확인한 뒤, 필요한 행동부터 순서대로 진행하세요.</p></article>`,`<article><b>4. 토큰과 기술 비용</b><p>기술 옆의 색 점은 필요한 토큰입니다. 턴 종료 시 원하는 토큰 1개를 얻어 다음 공격을 준비합니다. 색과 개수가 모두 충족되어야 기술을 사용할 수 있으므로 여러 턴에 걸쳐 계획하세요.</p></article>`,`<article><b>5. 특성·전략·진화</b><p>특성은 조건이 맞을 때 전투를 보조하고, 전략 카드는 흐름을 바꾸는 일회성 효과를 냅니다. 진화와 VMAX 카드는 더 강한 능력치를 제공하지만 덱 편성 제한과 사용 조건을 확인해야 합니다.</p></article>`,`<article><b>6. 피해 계산과 교체</b><p>공격 전 상대의 약점·저항과 남은 HP를 확인하세요. 피해로 HP가 0이 되면 해당 인물은 쓰러지고, 상대는 벤치에서 새 배틀 인물을 내보냅니다. 후퇴는 토큰을 소비할 수 있습니다.</p></article>`,`<article><b>7. 턴 종료와 전황 기록</b><p>할 행동을 마치면 턴을 종료합니다. 턴 종료 후 AI가 행동하며, 화면의 전황 기록에서 적용된 피해·회복·카드 효과를 확인할 수 있습니다. 기록을 보면 놓친 효과를 쉽게 파악할 수 있습니다.</p></article>`,`<article><b>8. 승리와 보상</b><p>상대 배틀 필드 인물의 HP를 0으로 만들면 승리합니다. 게임 중 더 이상 출전시킬 인물이 없거나 필수 조건을 충족하지 못하는 경우에도 승패가 결정될 수 있습니다. 보상과 도전과제 보상은 자동 지급됩니다.</p></article>`];const active=guideTab==="battle"?battle:basics;return `<section class="page guide-page"><div class="section-back"><button data-route="home">← 홈으로</button><span>이용 안내</span></div><div class="guide-hero"><span>?</span><div><p class="eyebrow">START HERE</p><h2>정켓몬스터 카드 게임 안내</h2><p>처음이라도 아래 순서대로 하면 바로 대전을 시작할 수 있습니다.</p></div></div><div class="guide-tabs"><button data-guide-tab="basics" class="${guideTab==="basics"?"active":""}">전반적인 이용 방법</button><button data-guide-tab="battle" class="${guideTab==="battle"?"active":""}">전투 진행 방식</button></div><div class="guide-grid">${active.join("")}</div></section>`;}
function patchView(){return `<section class="page patch-page"><div class="section-back"><button data-route="home">← 홈으로</button><span>패치 노트</span></div><div class="page-head"><p class="eyebrow">PATCH NOTES · v1.0.1</p><h2>1.0.1 버그 수정 및 밸런스 패치</h2><p>멀티 플레이 안정성과 카드 효과를 개선하고 일부 카드의 밸런스를 조정했습니다.</p></div><div class="patch-list"><article><b>멀티 플레이 수정</b><p>대전 종료 후 방에서 나갈 수 없던 문제, 상대 동전 연출 누락, 턴 변경 시 BGM 초기화, ‘나의 턴’ 안내 누락을 수정했습니다. 주진우 기술 2를 포함한 모든 동전형 기술·특성의 결과가 상대 화면에도 표시됩니다.</p></article><article><b>멀티 플레이 탈주 처리</b><p>대전 도중 방 나가기 메뉴를 추가했습니다. 확인 후 나가면 최대 30P의 탈주 페널티가 적용되며, 남은 상대는 승리와 승리 포인트를 받습니다.</p></article><article><b>카드 효과 개선</b><p>화면에는 앞면으로 표시됐지만 피해 계산에서는 뒷면으로 처리되던 동전 결과 전달 오류를 AI·멀티 플레이 모두 수정했습니다. 손패 선택·토큰 보존·카드 보호 효과도 설명대로 적용되도록 보완했습니다.</p></article><article><b>갤러리 새로고침</b><p>갤러리에 진입할 때마다 최신 게시글을 자동으로 불러오도록 변경했습니다.</p></article><article><b>밸런스 조정 · 박근혜</b><p>기술 ‘사드 배치’의 기본 피해를 50에서 40으로, 체력 조건 추가 피해를 20에서 10으로 낮췄습니다. 특성 ‘박정희의 딸’의 비빨강 대상 추가 피해도 20에서 10으로 낮췄습니다.</p></article><article><b>v1.0 정식 출시</b><p>계정, 갤러리, 카드 수집, AI 대전과 실시간 멀티 플레이 로비를 추가했습니다.</p></article></div></section>`;}
function collection(){const q=collectionSearch.trim().toLowerCase(),ownedCount=cards.filter(c=>(profile.collection[c.id]||0)>0).length,rarityRank=r=>RARITIES.indexOf(r)<0?RARITIES.length:RARITIES.indexOf(r),typeRank=c=>c.type==="character"?0:1,ownedRank=c=>(profile.collection[c.id]||0)>0?0:1,sorted=[...cards].sort((a,b)=>ownedRank(a)-ownedRank(b)||typeRank(a)-typeRank(b)||rarityRank(a.rarity)-rarityRank(b.rarity)||a.id.localeCompare(b.id)),filtered=sorted.filter(c=>{const cardPackList=cardPacks(c),searchText=`${c.name} ${c.id} ${c.description||""} ${c.trait?.name||""} ${attributeLabel(c.attribute)} ${cardPackList.map(p=>p.name).join(" ")}`.toLowerCase();return (collectionFilter==="ALL"||c.rarity===collectionFilter)&&(collectionPackFilter==="ALL"||cardPackList.some(p=>p.id===collectionPackFilter))&&(collectionAttributeFilter==="ALL"||c.attribute===collectionAttributeFilter)&&(!q||searchText.includes(q));});return `<section class="page"><div class="page-head"><p class="eyebrow">COLLECTION</p><h2>내 카드 도감</h2><p>보유한 카드 ${ownedCount}/${cards.length}종 · 보유 카드를 먼저 표시하고, 미보유 카드는 자물쇠로 표시됩니다.</p></div><div class="collection-tools"><input id="collection-search" placeholder="카드 이름, ID, 설명, 카드팩, 속성 검색" value="${escape(collectionSearch)}"><div class="filter-row"><button class="filter ${collectionFilter==="ALL"?"active":""}" data-rarity-filter="ALL">전체 등급</button>${RARITIES.map(r=>`<button class="filter ${collectionFilter===r?"active":""}" data-rarity-filter="${r}">${r}</button>`).join("")}</div><div class="filter-row attribute-filter-row"><button class="filter ${collectionAttributeFilter==="ALL"?"active":""}" data-attribute-filter="ALL">모든 속성</button>${settings.types.map(t=>`<button class="filter ${collectionAttributeFilter===t.id?"active":""}" data-attribute-filter="${t.id}">${t.label}</button>`).join("")}</div><div class="filter-row pack-filter-row"><button class="filter ${collectionPackFilter==="ALL"?"active":""}" data-pack-filter="ALL">모든 팩</button>${packs.map(p=>`<button class="filter ${collectionPackFilter===p.id?"active":""}" data-pack-filter="${p.id}">${p.name}</button>`).join("")}</div></div><div class="card-grid collection-grid">${filtered.map(c=>{const owned=(profile.collection[c.id]||0)>0,cardPackList=cardPacks(c),search=`${c.name} ${c.id} ${c.description||""} ${c.trait?.name||""} ${attributeLabel(c.attribute)} ${cardPackList.map(p=>p.name).join(" ")}`.toLowerCase();return `<div class="owned-card ${owned?"":"locked-card"}" data-card-detail="${c.id}" data-search="${escape(search)}">${cardArt(c,true)}<span class="owned-count">${owned?"× 1":"🔒"}</span></div>`;}).join("") || `<p class="empty">검색 결과가 없습니다.</p>`}</div></section>`;}
function deck(){const q=deckSearch.trim().toLowerCase(),rarityRank=r=>RARITIES.indexOf(r)<0?RARITIES.length:RARITIES.indexOf(r),typeRank=c=>c.type==="character"?0:1,owned=cards.filter(c=>(profile.collection[c.id]||0)>0).sort((a,b)=>typeRank(a)-typeRank(b)||rarityRank(a.rarity)-rarityRank(b.rarity)||a.id.localeCompare(b.id)).filter(c=>{const cardPackList=cardPacks(c),searchText=`${c.name} ${c.id} ${c.description||""} ${c.trait?.name||""} ${attributeLabel(c.attribute)} ${cardPackList.map(p=>p.name).join(" ")}`.toLowerCase();return (deckFilter==="ALL"||c.rarity===deckFilter)&&(deckPackFilter==="ALL"||cardPackList.some(p=>p.id===deckPackFilter))&&(deckAttributeFilter==="ALL"||c.attribute===deckAttributeFilter)&&(!q||searchText.includes(q));}),summary=deckCounts(profile.deck);const counts=id=>profile.deck.filter(x=>x===id).length,canAdd=c=>canDeckAcceptCard(profile.deck,c);return `<section class="page deck-page"><div class="section-back"><button data-route="home">← 홈으로</button><span>덱 편집</span></div><div class="page-head"><p class="eyebrow">DECK BUILDER</p><h2>나의 덱</h2><p>덱은 인물 카드 ${settings.characterLimit}장 + 전략 카드 ${settings.strategyLimit}장, 총 ${settings.deckCardCount}장으로 고정됩니다. VMAX는 최대 ${settings.vmaxLimit??2}장, SSR은 최대 ${settings.ssrLimit??2}장까지 넣을 수 있습니다.</p></div><div class="deck-summary"><div><span>총 카드</span><b>${profile.deck.length}/${settings.deckCardCount}</b></div><div><span>인물</span><b>${summary.characters}/${settings.characterLimit}</b></div><div><span>전략</span><b>${summary.strategies}/${settings.strategyLimit}</b></div><div><span>VMAX</span><b>${summary.vmax}/${settings.vmaxLimit??2}</b></div><div><span>SSR</span><b>${summary.ssr}/${settings.ssrLimit??2}</b></div><button class="btn ghost" id="reset-deck">기본 덱 복원</button></div><div class="deck-layout"><div><h3>덱 목록</h3><div class="deck-list">${profile.deck.length?profile.deck.map((id,i)=>`<button class="deck-row" data-remove-index="${i}"><span>${String(i+1).padStart(2,"0")}</span><b>${escape(cardById[id].name)}</b><em>${cardById[id].rarity}</em><i>×</i></button>`).join(""):`<p class="empty">카드를 추가해 주세요.</p>`}</div></div><div><h3>보유 카드</h3><div class="collection-tools deck-tools"><input id="deck-search" placeholder="카드 이름, ID, 설명, 카드팩, 속성 검색" value="${escape(deckSearch)}"><div class="filter-row"><button class="filter ${deckFilter==="ALL"?"active":""}" data-deck-rarity-filter="ALL">전체 등급</button>${RARITIES.map(r=>`<button class="filter ${deckFilter===r?"active":""}" data-deck-rarity-filter="${r}">${r}</button>`).join("")}</div><div class="filter-row attribute-filter-row"><button class="filter ${deckAttributeFilter==="ALL"?"active":""}" data-deck-attribute-filter="ALL">모든 속성</button>${settings.types.map(t=>`<button class="filter ${deckAttributeFilter===t.id?"active":""}" data-deck-attribute-filter="${t.id}">${t.label}</button>`).join("")}</div><div class="filter-row pack-filter-row"><button class="filter ${deckPackFilter==="ALL"?"active":""}" data-deck-pack-filter="ALL">모든 팩</button>${packs.map(p=>`<button class="filter ${deckPackFilter===p.id?"active":""}" data-deck-pack-filter="${p.id}">${p.name}</button>`).join("")}</div></div><div class="card-grid builder-grid">${owned.map(c=>`<div class="builder-card"><button class="builder-card-preview" data-card-info="${c.id}" type="button" title="카드 정보 보기">${cardArt(c,true)}</button><div><small>보유 1 · 덱 ${counts(c.id)}${isVmaxCard(c)?` · VMAX ${summary.vmax}/${settings.vmaxLimit??2}`:""}${c.rarity==="SSR"?` · SSR ${summary.ssr}/${settings.ssrLimit??2}`:""}</small>${counts(c.id)?`<button class="remove-card" data-remove-card="${c.id}">덱에서 제거 −</button>`:`<button class="add-card" data-add-card="${c.id}" ${canAdd(c)?"":"disabled"}>덱에 추가 +</button>`}</div></div>`).join("")||`<p class="empty">필터 결과가 없습니다.</p>`}</div></div></section>`;}
function packSummary(pack){const pool=packCards(pack),rarities=RARITIES.map(r=>`${r} ${pool.filter(c=>c.rarity===r).length}`).join(" · "),sample=pool.slice(0,10).map(c=>c.name).join(", ");return `<h3>${escape(pack.name)}</h3><p>${escape(pack.description)}</p><p>총 ${pool.length}종 · ${rarities}</p><small>${escape(sample)}${pool.length>10?" 외":""}</small>`;}
function packRarityTier(pack){const prices=[...new Set(packs.map(packPrice).filter(price=>price>0))].sort((a,b)=>b-a),rank=prices.indexOf(packPrice(pack));return rank===0?"legendary":rank===1?"epic":rank===2?"rare":"standard";}
function packsView(){const odds=Object.entries(settings.rarityOdds||{}).map(([r,n])=>`${r} ${n}%`).join(" · ");return `<section class="page"><div class="section-back"><button data-route="home">← 홈으로</button><span>카드 팩 센터</span></div><div class="page-head"><p class="eyebrow">CARD PACK CENTER</p><h2>카드 팩 센터</h2><p>팩 가격에 따라 외형 등급이 정해집니다. 최고가 팩은 금색, 다음은 은색, 그다음은 동색이며 금·은 팩에만 은은한 광택이 적용됩니다. 현재 임시 확률: ${odds}</p></div><div class="pack-grid">${packs.map((p,i)=>{const pool=packCards(p),price=packPrice(p),tier=packRarityTier(p);return `<article class="pack rarity-${tier}" data-pack-info="${p.id}"><div class="pack-art p${i%4}"><span>POLITIMON</span><b>${String(pool.length).padStart(2,"0")}</b></div><h3>${p.name}</h3><p>${p.description}</p><small>카드 풀 ${pool.length}종 · ${settings.cardsPerPack||10}장 개봉 · ${tier==="legendary"?"금색":tier==="epic"?"은색":tier==="rare"?"동색":"기본"} 등급</small><div class="pack-actions"><button class="btn ghost" data-pack-detail="${p.id}">정보</button><button class="btn ${pool.length?"primary":"disabled"}" data-open-pack="${p.id}" ${pool.length?"":"disabled"}>${pool.length?`${price?price+"P":"무료"} 개봉`:"카드 추가 대기"}</button></div></article>`;}).join("")}</div></section>`;}
function achievementsView(){const categories=["ALL",...new Set(achievements.map(a=>a.category||"기타"))],visible=achievements.filter(a=>achievementCategory==="ALL"||(a.category||"기타")===achievementCategory);return `<section class="page"><div class="page-head"><p class="eyebrow">ACHIEVEMENTS</p><h2>도전과제</h2><p>조건을 달성하면 재화 보상이 자동 지급됩니다. 전적: ${profile.records.plays||0}전 ${profile.records.wins||0}승 ${profile.records.losses||0}패 · AI ${profile.records.aiWins||0}승 · PvP ${profile.records.pvpWins||0}승</p></div><div class="filter-row achievement-categories">${categories.map(category=>`<button class="filter ${achievementCategory===category?"active":""}" data-achievement-category="${category}">${category==="ALL"?"전체":escape(category)} <small>${category==="ALL"?achievements.length:achievements.filter(a=>(a.category||"기타")===category).length}</small></button>`).join("")}</div><div class="achievement-grid">${visible.map(a=>{const value=metricValue(a.metric),done=!!profile.achievements[a.id],pct=Math.min(100,Math.floor(value/a.target*100));return `<article class="achievement ${done?"done":""}"><div><b>${escape(a.title)}</b><span>${done?"달성 완료":"진행 중"} · 보상 ${a.reward}P</span></div><em class="achievement-category">${escape(a.category||"기타")}</em><p>${escape(a.description)}</p><div class="achievement-bar"><i style="width:${pct}%"></i></div><small>${Math.min(value,a.target)} / ${a.target}</small></article>`;}).join("")}</div></section>`;}

function tokenDots(color,count){return Array.from({length:count},()=>`<i class="token-dot" style="--token-color:${tokenColor(color)}" title="${settings.tokenLabels[color]||color}"></i>`).join("");}
function tokenPills(tokens){const dots=settings.tokenTypes.flatMap(c=>Array.from({length:Math.max(0,tokens[c]||0)},()=>c));return dots.length?`<div class="token-stream">${dots.map(c=>`<i class="token-dot" style="--token-color:${tokenColor(c)}" title="${settings.tokenLabels[c]||c}"></i>`).join("")}</div>`:`<div class="token-stream empty-token">토큰 없음</div>`;}
function activeCard(active,enemy=false){if(!active)return `<div class="no-active">${enemy?"상대가 인물을 준비 중입니다":"인물을 배치하세요"}</div>`;if(active.faceDown)return `<div class="battle-card face-down-card ${enemy?"enemy":""}" aria-label="뒷면 카드"><div class="face-down-card-mark">P</div><b>뒷면 카드</b><small>동전 뒤집기로 활성화</small></div>`;const pct=Math.max(0,(active.currentHp/active.hp)*100),attrColor=tokenColor(active.attribute);return `<div class="battle-card ${enemy?"enemy":""}" data-card-info="${active.id}" title="카드 정보 보기" style="--card-attr-color:${attrColor}">${cardArt(active,true)}<div class="hp-readout"><span>HP</span><b>${Math.max(0,active.currentHp)} <small>/ ${active.hp}</small></b></div><div class="hp-bar"><i style="width:${pct}%"></i></div></div>`;}
function choiceCard(id,attr){return `<div class="choice-card-wrap"><button ${attr}="${id}">${cardArt(cardById[id],true)}</button><button class="mini-info" data-card-info="${id}">정보</button></div>`;}
function ruleText(active){if(!active)return "";if(active.faceDown)return `<aside class="rule-text facedown-rule"><b>뒷면 카드</b><p>동전을 던져 앞면이 나오기 전까지 이 카드는 사용할 수 없습니다.</p></aside>`;const meta=`<div class="matchup-line"><b><span>약점</span>${tokenDot(active.weakness)}</b><b><span>저항</span>${tokenDot(active.resistance)}</b><b><span>후퇴</span>${costDots(active.retreatCost)}</b></div>`,trait=active.trait?`<div><b>특성 · ${escape(active.trait.name)}</b><p>${escape(active.trait.description||"")}</p></div>`:"";const skills=(active.skills||[]).map((skill,i)=>`<div><b>기술${active.trait?"":i+1} · ${escape(skill.name)}</b><span>${costDots(skill.cost)}</span><p>${escape(skill.description||"")}</p></div>`).join("");return `<aside class="rule-text">${meta}${trait}${skills||"<div><b>기술 없음</b></div>"}</aside>`;}
function battleActions(me,isMyTurn,canUseStrategyTurn=isMyTurn){const skills=me.active?.skills||[],passiveTrait=me.active?.trait?.passive,manualTrait=me.active?.trait&&!me.active.trait.auto&&!passiveTrait,canTrait=isMyTurn||me.traitAfterSkillAvailable,canEvolve=isMyTurn&&me.hand?.some(id=>game.canEvolve(0,id)),first=manualTrait?`<button class="action-btn" id="trait-btn" ${!canTrait||me.traitUsedThisTurn?"disabled":""}>◇<span>특성</span></button>`:(skills[0]?`<button class="action-btn" data-use-skill-direct="0" ${!isMyTurn||!canUseSkill(me,skills[0])?"disabled":""}>⚡<span>기술1</span></button>`:`<div class="action-btn" aria-disabled="true">—<span>기술 없음</span></div>`),second=manualTrait?(skills[0]?`<button class="action-btn" data-use-skill-direct="0" ${!isMyTurn||!canUseSkill(me,skills[0])?"disabled":""}>⚡<span>기술</span></button>`:`<div class="action-btn" aria-disabled="true">—<span>기술 없음</span></div>`):(skills[1]?`<button class="action-btn" data-use-skill-direct="1" ${!isMyTurn||!canUseSkill(me,skills[1])?"disabled":""}>⚡<span>기술2</span></button>`:`<div class="action-btn" aria-disabled="true" title="${passiveTrait?"패시브 특성은 자동 적용됩니다.":"이 카드에는 수동 특성이 없습니다"}">—<span>${passiveTrait?"패시브":"특성 없음"}</span></div>`);return `${first}${second}<button class="action-btn" id="evolve-btn" ${!canEvolve?"disabled":""}>⬆<span>진화</span></button><button class="action-btn" id="retreat-btn" ${!isMyTurn||!me.active?"disabled":""}>↩<span>후퇴</span></button><button class="action-btn" id="strategy-btn" ${!canUseStrategyTurn?"disabled":""}>✦<span>전략</span></button>`;}
function gameView(){if(!game)return home();const s=game.snapshot(),me=s.players[0],ai=s.players[1],pvpLocked=!!pvpSession?.pending,isMyTurn=s.turn===0&&s.phase==="playing"&&s.actionAvailable&&!pvpLocked,canUseStrategyTurn=s.turn===0&&s.phase==="playing"&&s.winner==null&&!pvpLocked,canEndTurn=s.turn===0&&["playing","forced-end"].includes(s.phase)&&s.winner==null&&!pvpLocked;if(s.phase==="finished")grantMatchReward(s.winner,{pvp:isPvpMatch()});let actionPanel="";
 if(s.phase==="setup-bonus")actionPanel=`<div class="game-prompt"><b>후공 보너스</b><p>덱 맨 위 카드를 확인하고, 원하면 손패 1장과 교환할 수 있습니다.</p><button class="btn primary" id="inspect-top">덱 맨 위 확인</button><button class="btn secondary" id="skip-bonus">그대로 진행</button></div>`;
 else if(s.phase==="choose-active"||s.phase==="choose-replacement"){const choosing=isPvpMatch()?s.turn:(s.phase==="choose-replacement"?s.turn:(s.initialAIDone?0:s.first)); if(choosing===0){const forced=s.phase==="choose-replacement"&&me.forcedReplacement;actionPanel=`<div class="game-prompt"><b>${forced?"강제 교체":"인물 배치"}</b><p>${forced?"이번 턴은 새 인물 배치 후 바로 종료됩니다.":"손패에서 인물 카드 1장을 선택하세요."}</p><div class="choice-cards">${me.hand.filter(id=>cardById[id].type==="character"&&!isVmaxCard(cardById[id])).map(id=>choiceCard(id,"data-play-character")).join("")||"<p>배치할 인물 카드가 없습니다.</p>"}</div></div>`;}else actionPanel=`<div class="game-prompt"><b>${isPvpMatch()?"상대가 인물을 고르는 중입니다…":"AI가 인물을 고르는 중..."}</b></div>`;}
 else if(s.phase==="forced-end")actionPanel=`<div class="game-prompt"><b>강제 교체 완료</b><p>다른 행동은 할 수 없습니다. 턴 종료 토큰을 선택하세요.</p><div>${settings.tokenTypes.map(c=>`<button class="token-choice" style="--token-color:${tokenColor(c)}" data-end-turn="${c}">${settings.tokenLabels[c]}</button>`).join("")}</div></div>`;
 else if(s.phase==="finished")actionPanel=`<div class="game-prompt finish"><b>${s.winner===0?"승리했습니다!":"패배했습니다"}</b><p>${matchRewardText(s,isPvpMatch())}</p><button class="btn primary" id="return-home">메인으로</button></div>`;
 else if(me.active?.faceDown&&s.turn===0)actionPanel=`<div class="game-prompt face-down-prompt"><b>뒷면 카드 판정</b><p>카드가 비활성화되었습니다. 동전을 던져 앞면이 나오면 다시 활성화되며, 결과와 관계없이 턴이 끝납니다.</p><button class="btn primary" id="face-down-coin">동전 던지기</button></div>`;
 else actionPanel=`<div class="action-panel"><div class="action-top"><span>${s.turn===0?"나의 턴":"상대의 턴"}</span><span>${s.actionAvailable?"행동 1회 가능":"행동 완료 · 전략/토큰 선택"}</span></div><div class="actions">${battleActions(me,isMyTurn,canUseStrategyTurn)}</div><div class="end-turn"><span>턴 종료 시 원하는 토큰 1개 획득</span><div>${settings.tokenTypes.map(c=>`<button class="token-choice" style="--token-color:${tokenColor(c)}" data-end-turn="${c}" ${!canEndTurn?"disabled":""}>${settings.tokenLabels[c]}</button>`).join("")}</div></div></div>`;
 const names=isPvpMatch()?pvpNames():{me:"LOCAL TRAINER",opponent:game.aiOpponent?.name||"AI"},exitControl=isPvpMatch()&&s.phase!=="finished"?`<button class="back forfeit-exit" id="forfeit-pvp" ${pvpLocked?"disabled":""}>← 방 나가기</button>`:`<button class="back" data-route="home">← 나가기</button>`;return `<section class="game"><div class="game-header">${exitControl}<div><span>${isPvpMatch()?"REALTIME PVP":"AI MATCH"}</span><b>${s.phase==="finished"?"MATCH END":s.turn===0?"YOUR TURN":isPvpMatch()?"OPPONENT TURN":"AI TURN"}</b></div><div class="game-tools"><span class="turn-count">인물 사용 ${me.characterUses}/3</span></div></div><div class="arena"><div class="opponent-zone"><div class="combatant-label"><b>${escape(names.opponent)} · ${isPvpMatch()?"ONLINE":"OPPONENT"}</b><span>덱 ${ai.deck.length} · 손패 ${ai.hand.length}</span></div>${activeCard(ai.active,true)}${ruleText(ai.active)}<div class="token-row">${tokenPills(ai.tokens)}</div></div><div class="versus">VS</div><div class="player-zone"><div class="combatant-label"><b>${escape(names.me)}</b><span>덱 ${me.deck.length} · 손패 ${me.hand.length}</span></div>${activeCard(me.active)}${ruleText(me.active)}<div class="token-row">${tokenPills(me.tokens)}</div></div></div><section class="hand"><div class="hand-head"><b>내 손패</b><span>${me.hand.length} CARDS</span></div><div class="hand-cards">${me.hand.map(id=>`<button class="hand-card" data-hand-card="${id}" ${(cardById[id].type==="strategy"||cardById[id].trait?.treatAsStrategy)&&!canUseStrategyTurn?"disabled":""}>${cardArt(cardById[id],true)}</button>`).join("")||"<p>손패가 없습니다.</p>"}</div></section>${actionPanel}<section class="battle-log"><b>전황 기록</b>${s.log.slice(0,4).map(x=>`<p>${escape(x)}</p>`).join("")}</section></section>`;}

function render(){applyUiPrefs();document.querySelector("#currency-count").textContent=profile.currency;updateHeaderUser();updateNotificationBadge();const bottomNav=document.querySelector(".bottom-nav");if(bottomNav)bottomNav.hidden=roomNavigationLocked();document.querySelectorAll(".bottom-nav button").forEach(b=>b.classList.toggle("active",b.dataset.route===route));const backLabels={collection:"도감",achievements:"도전과제"},views={home,auth:authView,multiplayer:multiplayerView,gallery:galleryView,ai:aiSelect,guide:guideView,patch:patchView,collection,deck,packs:packsView,achievements:achievementsView,game:gameView},back=backLabels[route]?`<div class="section-back global-back"><button id="global-back" type="button">← 홈으로</button><span>${backLabels[route]}</span></div>`:"";app.innerHTML=back+(views[route]||home)();app.classList.remove("page-enter");void app.offsetWidth;app.classList.add("page-enter");bind();if(route==="gallery"&&!galleryLoaded&&!galleryLoading)loadGalleryPosts();if(route==="multiplayer"&&!activeRoom&&!roomsLoaded&&!roomsLoading)loadRooms();if(route==="home"){const menu=document.querySelector(".primary-menu"),button=document.createElement("button");button.type="button";button.className="metro-menu tutorial-entry";button.innerHTML=`<span>◎</span><div><b>튜토리얼</b><small>고정된 카드와 순서로 기본 전투를 배웁니다</small></div><i>→</i>`;button.onclick=startTutorial;menu?.prepend(button);}addSearchButton("collection-search","collection");addSearchButton("deck-search","deck");const resetDeckButton=document.querySelector("#reset-deck");if(resetDeckButton){const autoDeckButton=resetDeckButton.cloneNode(true);resetDeckButton.replaceWith(autoDeckButton);autoDeckButton.id="auto-build-deck";autoDeckButton.textContent="자동 덱 짜기";autoDeckButton.onclick=autoBuildDeck;}if(route==="ai"){document.querySelector(".ai-deck-shortcut")?.remove();const launch=document.querySelector(".ai-launch");if(launch){const deckButton=document.createElement("button");deckButton.type="button";deckButton.className="btn ghost ai-launch-deck";deckButton.textContent="▤ 덱 편집";deckButton.onclick=()=>go("deck");launch.insertBefore(deckButton,launch.querySelector("[data-start-ai]"));}}if(route==="game"&&game?.tutorial){document.querySelector(".game")?.insertAdjacentHTML("afterbegin",tutorialGuide());}updateAudioControls();syncRouteMusic();}
function modal(content,{closeAction=null}={}){modalRoot.innerHTML=`<div class="modal-backdrop"><div class="modal">${content}<button class="modal-close" id="close-modal">×</button></div></div>`;document.querySelector("#close-modal").onclick=closeAction||(()=>modalRoot.innerHTML="");const backdrop=modalRoot.querySelector(".modal-backdrop");backdrop.onclick=e=>{if(e.target===backdrop&&backdrop.querySelector(".settings-panel-rich"))modalRoot.innerHTML="";};}
function keepModalOpenOnClose(onClose=()=>{}){document.querySelector("#close-modal").onclick=e=>{e.preventDefault();e.stopPropagation();choiceCancelled=true;modalRoot.innerHTML="";onClose();};}
function chooseToken({caption="토큰 선택",available=null}={}){if(choiceCancelled)return Promise.resolve(null);return new Promise(resolve=>{const colors=settings.tokenTypes.filter(c=>available?(available[c]||0)>0:true);if(!colors.length){resolve(null);return;}modal(`<h3>${escape(caption)}</h3><div class="token-picker">${colors.map(c=>`<button class="token-choice" style="--token-color:${tokenColor(c)}" data-pick-token="${c}">${settings.tokenLabels[c]}${available?` <small>${available[c]}</small>`:""}</button>`).join("")}</div>`);const finish=color=>{modalRoot.innerHTML="";resolve(color);};keepModalOpenOnClose(()=>finish(null));document.querySelectorAll("[data-pick-token]").forEach(b=>b.onclick=()=>finish(b.dataset.pickToken));});}
function bindSettingsModal(){document.querySelector("#toggle-reduced-motion")?.addEventListener("click",e=>{e.stopPropagation();uiPrefs.reducedMotion=!uiPrefs.reducedMotion;saveUiPrefs();applyUiPrefs();render();openGameSettings();});document.querySelector("#toggle-compact-cards")?.addEventListener("click",e=>{e.stopPropagation();uiPrefs.compactCards=!uiPrefs.compactCards;saveUiPrefs();applyUiPrefs();render();openGameSettings();});}
function openGameSettings(){modal(`<div class="settings-title"><span>⚙</span><div><h3>환경 설정</h3><p>설정은 이 브라우저에 자동으로 저장됩니다.</p></div></div><div class="settings-panel settings-panel-rich"><section class="setting-section"><div><b>배경 음악</b><small>홈에서는 home.mp3, 전투에서는 bgm.mp3가 재생됩니다.</small></div><button class="setting-toggle ${audioPrefs.music?"on":""}" id="toggle-music"><b>${audioPrefs.music?"ON":"OFF"}</b></button><label class="volume-control"><span>볼륨 <b id="volume-value">${audioPrefs.volume}%</b></span><input id="music-volume" type="range" min="0" max="100" value="${audioPrefs.volume}" ${audioPrefs.music?"":"disabled"}></label></section><section class="setting-section"><div><b>효과음 및 연출</b><small>스킬, 타격, 동전, 카드팩 연출의 소리와 효과를 켜거나 끕니다.</small></div><button class="setting-toggle ${audioPrefs.effects?"on":""}" id="toggle-effects"><b>${audioPrefs.effects?"ON":"OFF"}</b></button></section><section class="setting-section"><div><b>부드러운 화면 전환</b><small>메뉴 전환의 짧은 페이드·슬라이드 효과를 조절합니다.</small></div><button class="setting-toggle ${uiPrefs.reducedMotion?"":"on"}" id="toggle-reduced-motion"><b>${uiPrefs.reducedMotion?"OFF":"ON"}</b></button></section><section class="setting-section"><div><b>도감 카드 밀도</b><small>도감에서 한 화면에 더 많은 카드를 표시합니다.</small></div><button class="setting-toggle ${uiPrefs.compactCards?"on":""}" id="toggle-compact-cards"><b>${uiPrefs.compactCards?"조밀":"기본"}</b></button></section></div>`);updateAudioControls();bindSettingsModal();}
function openProfile(){if(!currentUser()){go("auth");return;}const owned=cards.filter(c=>(profile.collection[c.id]||0)>0).length;modal(`<div class="profile-modal"><span class="profile-avatar large">${escape(displayName(currentUser())[0])}</span><div><h3>${escape(displayName(currentUser()))}</h3><p>${escape(currentUser().email||"")} · 카드를 모으고 전적을 쌓아 보세요.</p></div></div><div class="profile-stats"><div><span>보유 카드</span><b>${owned}/${cards.length}</b></div><div><span>대전</span><b>${profile.records.plays||0}</b></div><div><span>승리</span><b>${profile.records.wins||0}</b></div></div><div class="modal-actions"><button class="btn secondary" data-route="auth">계정 관리</button><button class="btn secondary" data-route="deck">덱 편집</button><button class="btn ghost" id="reset-profile">진행 초기화</button></div>`);modalRoot.querySelector("#reset-profile").onclick=()=>modal(`<h3>진행 상황 초기화</h3><p>재화, 카드 보유, 덱, 전적, 도전과제를 초기 상태로 되돌립니다. 기본 재화는 500P입니다.</p><button class="btn primary" id="confirm-reset-profile">초기화 실행</button>`);}
function openNotifications(){const items=notifications.length?notifications.map(n=>`<article class="notification-item ${n.unread?"unread":""}"><b>${escape(n.title)}</b><p>${escape(n.message)}</p></article>`).join(""):`<p class="empty notification-empty">도전과제를 달성하면 알림이 이곳에 쌓입니다.</p>`;notifications=notifications.map(n=>({...n,unread:false}));saveNotifications();updateNotificationBadge();modal(`<h3>알림</h3><div class="notification-list">${items}</div>`);}
function optionalWording(text=""){return /선택할 수 있다|선택할 수 있습니다|할 수 있다|할 수 있습니다/.test(text);}
function effectAppliesToState(e,source,state=game?.snapshot()){const enemy=state?.players?.[1-source];if(e.type==="coinFlipBonusOrSelfDamageIfEnemyAttribute")return enemy?.active?.attribute===e.attribute;if(e.type==="coinFlipBonusDamageUnlessEnemyAttribute")return enemy?.active?.attribute!==e.attribute;return true;}
function bestAvailableToken(tokens={},exclude=null){return settings.tokenTypes.filter(c=>c!==exclude&&(tokens[c]||0)>0).sort((a,b)=>(tokens[b]||0)-(tokens[a]||0))[0]||null;}
function showAiChoiceEffect({label="",caption="AI SELECT",lines=[]}={}){return enqueueVisualEffect(resolve=>{const veil=document.createElement("div"),panel=document.createElement("div"),title=document.createElement("b"),sub=document.createElement("span"),list=document.createElement("div");veil.className="ai-choice-veil";panel.className="ai-choice-panel";sub.textContent=caption;title.append(sub,document.createTextNode(label||"AI 선택"));list.className="ai-choice-lines";(lines.length?lines:["자동 선택 완료"]).forEach(line=>{const item=document.createElement("i");item.textContent=line;list.append(item);});panel.append(title,list);veil.append(panel);document.body.append(veil);setTimeout(()=>veil.classList.add("settled"),220);setTimeout(()=>{veil.remove();resolve();},EFFECT_DURATION_MS);});}
function chooseYesNo({caption="선택",body="",yesLabel="사용",noLabel="사용 안 함"}={}){if(choiceCancelled)return Promise.resolve(null);return new Promise(resolve=>{modal(`<h3>${escape(caption)}</h3>${body?`<p>${escape(body)}</p>`:""}<div class="modal-actions"><button class="btn primary" id="choice-yes">${escape(yesLabel)}</button><button class="btn secondary" id="choice-no">${escape(noLabel)}</button></div>`);const finish=value=>{modalRoot.innerHTML="";resolve(value);};keepModalOpenOnClose(()=>finish(null));document.querySelector("#choice-yes").onclick=()=>finish(true);document.querySelector("#choice-no").onclick=()=>finish(false);});}
function chooseHandCharacter({caption="제거할 인물 선택",optional=false,effect={}}={}){if(choiceCancelled)return Promise.resolve(null);return new Promise(resolve=>{const ids=game.snapshot().players[0].hand.filter(id=>{const c=cardById[id];return c?.type==="character"&&!isVmaxCard(c)&&id!==effect.excludeCardId&&(!effect.cardId||id===effect.cardId)&&(!effect.name||c.name===effect.name);});if(!ids.length){resolve(null);return;}modal(`<h3>${escape(caption)}</h3><p>${optional?"선택하지 않고 기술을 사용할 수도 있습니다.":"인물 카드를 선택하세요."}</p><div class="choice-cards">${ids.map(id=>choiceCard(id,"data-pick-hand-character")).join("")}</div>${optional?`<button class="btn secondary" id="skip-hand-character">선택하지 않기</button>`:""}`);const finish=id=>{modalRoot.innerHTML="";resolve(id);};keepModalOpenOnClose(()=>finish(null));document.querySelector("#skip-hand-character")?.addEventListener("click",()=>finish(null));document.querySelectorAll("[data-pick-hand-character]").forEach(b=>b.onclick=()=>finish(b.dataset.pickHandCharacter));});}
function chooseAnyHandCard({caption="손패 카드 선택",optional=false,excludeId=null}={}){if(choiceCancelled)return Promise.resolve(null);return new Promise(resolve=>{const ids=game.snapshot().players[0].hand.filter(id=>id!==excludeId);if(!ids.length){resolve(null);return;}modal(`<h3>${escape(caption)}</h3><p>${optional?"선택하지 않고 진행할 수도 있습니다.":"손패 카드를 선택하세요."}</p><div class="choice-cards">${ids.map(id=>choiceCard(id,"data-pick-hand-card")).join("")}</div>${optional?`<button class="btn secondary" id="skip-hand-card">선택하지 않기</button>`:""}`);const finish=id=>{modalRoot.innerHTML="";resolve(id);};keepModalOpenOnClose(()=>finish(null));document.querySelector("#skip-hand-card")?.addEventListener("click",()=>finish(null));document.querySelectorAll("[data-pick-hand-card]").forEach(b=>b.onclick=()=>finish(b.dataset.pickHandCard));});}
function chooseTrashCharacter({caption="트래쉬 카드 선택",effect={}}={}){if(choiceCancelled)return Promise.resolve(null);return new Promise(resolve=>{const ids=game.snapshot().players[0].discard.filter(id=>{const c=cardById[id];return c?.type==="character"&&(!effect.attribute||c.attribute===effect.attribute)&&(!effect.name||c.name===effect.name)&&(!effect.cardId||id===effect.cardId);});if(!ids.length){resolve(null);return;}modal(`<h3>${escape(caption)}</h3><p>손패로 가져올 트래쉬의 인물 카드를 선택하세요.</p><div class="choice-cards">${ids.map(id=>choiceCard(id,"data-pick-trash-character")).join("")}</div>`);const finish=id=>{modalRoot.innerHTML="";resolve(id);};keepModalOpenOnClose(()=>finish(null));document.querySelectorAll("[data-pick-trash-character]").forEach(b=>b.onclick=()=>finish(b.dataset.pickTrashCharacter));});}
function chooseEnemyHiddenHandCard({caption="상대 손패 선택"}={}){if(choiceCancelled)return Promise.resolve(null);return new Promise(resolve=>{const ids=game.snapshot().players[1].hand;if(!ids.length){resolve(null);return;}modal(`<h3>${escape(caption)}</h3><p>상대 손패의 뒷면 카드 중 하나를 고른 뒤, 다음 단계에서 그 카드의 속성을 추측합니다.</p><div class="hidden-hand-picker">${ids.map((id,i)=>`<button class="hidden-hand-card" data-pick-hidden-hand="${escape(id)}"><span>POLITIMON</span><b>${i+1}</b><small>상대 손패</small></button>`).join("")}</div>`);const finish=id=>{modalRoot.innerHTML="";resolve(id);};keepModalOpenOnClose(()=>finish(null));document.querySelectorAll("[data-pick-hidden-hand]").forEach(b=>b.onclick=()=>finish(b.dataset.pickHiddenHand));});}
function chooseRevealedEnemyHandCard(ids,{caption="가져올 카드 선택"}={}){if(choiceCancelled||!ids?.length)return Promise.resolve(null);return new Promise(resolve=>{modal(`<h3>${escape(caption)}</h3><p>확인한 카드 중 내 손패로 가져올 카드를 선택하세요.</p><div class="choice-cards">${ids.map(id=>choiceCard(id,"data-pick-revealed-enemy-card")).join("")}</div>`);const finish=id=>{modalRoot.innerHTML="";resolve(id);};keepModalOpenOnClose(()=>finish(null));document.querySelectorAll("[data-pick-revealed-enemy-card]").forEach(b=>b.onclick=()=>finish(b.dataset.pickRevealedEnemyCard));});}
function chooseStrategyChoice(card){if(choiceCancelled)return Promise.resolve(null);return new Promise(resolve=>{if(!card?.choices?.length){resolve({index:null,effects:card?.effects||[],description:card?.description||""});return;}modal(`<h3>${escape(card.name)} 효과 선택</h3><div class="skill-list">${card.choices.map((choice,i)=>`<button data-pick-strategy-choice="${i}"><b>${escape(choice.label||`효과 ${i+1}`)}</b><small>${escape(choice.description||"")}</small></button>`).join("")}</div>`);const finish=index=>{const choice=card.choices[index];if(!choice)return;modalRoot.innerHTML="";resolve({index,effects:choice.effects||[],description:choice.description||card.description||""});};keepModalOpenOnClose(()=>resolve(null));document.querySelectorAll("[data-pick-strategy-choice]").forEach(b=>b.onclick=()=>finish(Number(b.dataset.pickStrategyChoice)));});}
function cardDetail(id){const c=cardById[id];if(!c)return;const owned=(profile.collection[c.id]||0)>0,packNames=cardPacks(c).map(p=>p.name).join(", ")||"미지정",meta=c.type==="character"?`<div class="detail-meta"><div><span>HP</span><b>${c.hp}</b></div><div><span>속성</span>${tokenDot(c.attribute)}</div><div><span>약점</span>${tokenDot(c.weakness)}</div><div><span>저항</span>${tokenDot(c.resistance)}</div><div><span>후퇴</span>${costDots(c.retreatCost)}</div></div>`:escape(c.description);modal(`<div class="detail">${cardArt(c)}<div><p class="eyebrow">${typeLabel(c.type)} · ${c.rarity} · ${owned?"보유":"미보유"}</p><h2>${escape(c.name)}</h2>${c.type==="character"?meta:`<p>${meta}</p>`}<h4>수록 카드팩</h4><p>${escape(packNames)}</p>${c.type==="character"&&c.description?`<h4>설명</h4><p>${escape(c.description)}</p>`:""}${c.trait?`<h4>특성 · ${escape(c.trait.name)}</h4><p>${escape(c.trait.description)}</p>`:""}${c.skills?.map(s=>`<h4>기술 · ${escape(s.name)} <small>${costDots(s.cost)}</small></h4><p>${escape(s.description)}</p>`).join("")||""}</div></div>`);}
async function openPack(packId){const pack=packs.find(p=>p.id===packId);if(!pack)return;const price=packPrice(pack);if(price&&profile.currency<price){notify("재화가 부족합니다.");return;}const pulled=drawFromPack(pack);if(!pulled.length){notify("이 팩에는 아직 카드가 없습니다.");return;}await showPackOpening(pack);const duplicateIds=new Set(pulled.filter(card=>(profile.collection[card.id]||0)>0).map(card=>card.id));if(price)profile.currency-=price;pulled.forEach(card=>profile.collection[card.id]=1);profile.records.packsOpened=(profile.records.packsOpened||0)+1;profile.records.cardsPulled=(profile.records.cardsPulled||0)+pulled.length;save();checkAchievements();modal(`<h3>${pack.name} 개봉 결과</h3>${duplicateIds.size?`<p class="pack-duplicate-note">중복 ${duplicateIds.size}종 · 중복 카드는 재화로 환급되지 않습니다.</p>`:""}<div class="card-grid collection-grid pack-results">${pulled.map((card,i)=>`<div class="owned-card" data-card-detail="${card.id}" style="--reveal-delay:${i*.12}s">${cardArt(card,true)}<span class="owned-count">${card.rarity}${duplicateIds.has(card.id)?" · 중복":""}</span></div>`).join("")}</div>`);render();}
async function playerCoinContext(label,effects,description="",sourceCardId=null){
  choiceCancelled=false;const context={},snapshot=game.snapshot(),player=snapshot.players[0],enemy=snapshot.players[1],forced=player.forceNextCoinHeads?"heads":null;
  if(!description){
    const active=player.active;
    const handCard=player.hand.map(id=>cardById[id]).find(c=>c?.name===label&&c.effects===effects);
    if(active?.trait?.effects===effects)description=active.trait.description||"";
    else if(handCard)description=handCard.description||"";
  }
  const optionalText=optionalWording(description);
  const coinTypes=COIN_EFFECT_TYPES;
  const coinEffects=(effects||[]).filter(e=>coinTypes.includes(e.type)&&effectAppliesToState(e,0,snapshot));
  if((effects||[]).some(e=>e.type==="guessRandomHandCardAttributeBonus")){context.guessedHandId=await chooseEnemyHiddenHandCard({caption:`${label} · 상대 손패 카드 선택`});context.guessedAttribute=await chooseToken({caption:`${label} · 선택한 카드의 속성 추측`});}
  if((effects||[]).some(e=>e.type==="revealChosenEnemyHand"))context.revealHandId=await chooseEnemyHiddenHandCard({caption:`${label} · 확인할 상대 손패 선택`});
  if((effects||[]).some(e=>e.type==="stealToken"))context.stealColor=await chooseToken({caption:`${label} · 가져올 토큰 선택`,available:enemy.tokens});
  const convertEffect=(effects||[]).find(e=>e.type==="convertEnemyToken");
  if(convertEffect){
    const available=Object.fromEntries(settings.tokenTypes.filter(c=>c!==convertEffect.to&&(enemy.tokens[c]||0)>0).map(c=>[c,enemy.tokens[c]]));
    context.convertEnemyColor=await chooseToken({caption:`${label} · ${settings.tokenLabels[convertEffect.to]||convertEffect.to}(으)로 바꿀 상대 토큰 선택`,available});
  }
  const discardEffect=(effects||[]).find(e=>e.type==="optionalDiscardCharacterFromHand"||e.type==="discardCharacterFromHand");
  if(discardEffect)context.discardCharacterId=await chooseHandCharacter({caption:`${label} · 제거할 인물 카드 선택`,optional:discardEffect.type==="optionalDiscardCharacterFromHand",effect:discardEffect});
  if((effects||[]).some(e=>e.type==="discardAnyHandCardThenDefeatEnemy"))context.discardHandId=await chooseAnyHandCard({caption:`${label} · 트래쉬할 손패 선택`,excludeId:sourceCardId});
  if((effects||[]).some(e=>e.type==="discardPreferredHandCardForBonusDamage"))context.discardHandId=await chooseAnyHandCard({caption:`${label} · 추가 피해용 손패 선택`,optional:true});
  if((effects||[]).some(e=>e.type==="swapHandCardWithEnemy")){context.ownHandId=await chooseAnyHandCard({caption:`${label} · 교환할 내 손패 선택`});context.enemyHandId=await chooseEnemyHiddenHandCard({caption:`${label} · 교환할 상대 손패 선택`});}
  if((effects||[]).some(e=>e.type==="spyTwoEnemyCardsStealOneAndReplace"))context.stealHandId=await chooseRevealedEnemyHandCard(enemy.hand.slice(0,2),{caption:`${label} · 가져올 상대 카드 선택`});
  const playHandEffect=(effects||[]).find(e=>e.type==="playHandCharacterAsStrategyNoCount");
  if(playHandEffect)context.handCharacterId=await chooseHandCharacter({caption:`${label} · 배치할 인물 카드 선택`,effect:playHandEffect});
  const recoverEffect=(effects||[]).find(e=>e.type==="recoverCharacterFromTrash"||e.type==="recoverCharacterFromTrashToDeck");
  if(recoverEffect)context.trashCharacterId=await chooseTrashCharacter({caption:`${label} · 트래쉬에서 가져올 인물 선택`,effect:recoverEffect});
  if((effects||[]).some(e=>e.type==="gainTokenIfDefeats"||e.type==="convertOwnTokenToActiveAttribute"||e.type==="convertOwnTokenToChosenColor"||e.type==="convertAllEnemyTokensByColor"||e.type==="changeSelfAttribute"||((e.type==="addToken"||e.type==="attachToken")&&e.color==="any")))context.tokenColor=await chooseToken({caption:`${label} · 원하는 색 선택`});
  const tradeEffect=(effects||[]).find(e=>e.type==="discardOwnTokensDrawThenDiscardHandBonusDamage"&&e.optional);
  if(tradeEffect){
    const useTrade=await chooseYesNo({caption:`${label} · 선택 효과`,body:"갈색 토큰과 손패를 트래쉬해 추가 피해를 적용할까요?",yesLabel:"사용",noLabel:"사용 안 함"});
    if(!useTrade)context.skipOptionalTrade=true;
  }
  const selfDefeatEffect=(effects||[]).find(e=>e.type==="optionalDefeatSelfForBonusDamage");
  if(selfDefeatEffect)context.defeatSelfForBonus=await chooseYesNo({caption:`${label} · 선택 효과`,body:"이 기술 뒤 내 인물을 트래쉬하고 추가 피해를 적용할까요?",yesLabel:"추가 피해",noLabel:"기본 피해만"});
  if(coinEffects.length&&(coinEffects.some(e=>e.optional)||optionalText)){
    const useCoin=await chooseYesNo({caption:`${label} · 선택 효과`,body:"동전 뒤집기 효과를 적용할까요?",yesLabel:"동전 뒤집기",noLabel:"기본 피해만"});
    context.optionalText=optionalText;
    if(!useCoin)context.skipOptionalCoinFlip=true;
  }
  for(const e of effects||[]){
    if(coinTypes.includes(e.type)&&!effectAppliesToState(e,0,snapshot))continue;
    if(context.skipOptionalCoinFlip&&(e.optional||context.optionalText)&&coinEffects.includes(e))continue;
    if(e.type==="coinFlipDamageModifier"||e.type==="coinFlipSelfDamageOnTails"||e.type==="coinFlipHealSelfOrBonusDamage"){
      context.coinResult=await showCoinFlip({caption:label||"동전 뒤집기",headsLabel:"앞면",tailsLabel:"뒷면",result:forced||undefined});
      break;
    }
    if(e.type==="fixedCoinFlipsDamageBonus"||e.type==="fixedCoinFlipsAllHeadsAddToken"||e.type==="coinFlipAddTokensByResult"){
      context.coinResults=[];
      for(let i=0;i<(e.flips||1);i++)context.coinResults.push(await showCoinFlip({caption:`${label||"동전 뒤집기"} ${i+1}/${e.flips||1}`,headsLabel:"앞면",tailsLabel:"뒷면",result:forced&&i===0?forced:undefined}));
      break;
    }
    if(e.type==="coinFlipsDamageBonusAndSelfDamage"){
      context.coinResults=[];
      for(let i=0;i<(e.flips||1);i++)context.coinResults.push(await showCoinFlip({caption:`${label||"동전 뒤집기"} ${i+1}/${e.flips||1}`,headsLabel:"앞면",tailsLabel:"뒷면",result:forced&&i===0?forced:undefined}));
      break;
    }
    if(e.type==="pushYourLuckDamageModifier"){
      context.coinResults=[];
      let result="heads",guard=0,max=e.maxFlips||8;
      while(result==="heads"&&guard<max){
        result=await showCoinFlip({caption:`${label||"동전 뒤집기"} ${guard+1}/${max}`,headsLabel:"앞면",tailsLabel:"뒷면",result:forced&&guard===0?forced:undefined});
        context.coinResults.push(result);
        guard++;
        if(result==="heads"&&guard<max){
          const keepGoing=await chooseYesNo({caption:`${label} · 계속 뒤집기`,body:`현재 추가 피해 ${guard*(e.headsBonus||0)}. 그만두면 적용하고, 계속하다 뒷면이 나오면 추가 피해를 모두 잃고 반동 ${e.tailsSelfDamage||0} 피해를 받습니다.`,yesLabel:"한 번 더",noLabel:"그만"});
          if(!keepGoing)break;
        }
      }
      break;
    }
    if(e.type==="repeatCoinBonusUntilTails"){
      context.coinResults=await showCoinSeries({caption:label||"동전 뒤집기",maxFlips:e.maxFlips||8,forced});
      break;
    }
    if(e.type==="streakCoinDamageModifier"){
      context.coinResults=await showCoinSeries({caption:label||"동전 뒤집기",maxFlips:e.maxFlips||e.headsBonuses?.length||3,forced});
      break;
    }
    if(e.type==="coinFlipBonusDamageStealTokenOrSelfDamage"||e.type==="coinFlipBonusDamageUnlessEnemyAttribute"||e.type==="coinFlipBonusOrSelfDamageIfEnemyAttribute"||e.type==="recoverThisStrategyOnCoinHeads"||e.type==="coinFlipStealToken"||e.type==="coinFlipBonusDamageOrHealEnemy"){
      context.coinResult=await showCoinFlip({caption:label||"동전 뒤집기",headsLabel:"앞면",tailsLabel:"뒷면",result:forced||undefined});
      break;
    }
  }
  context.tokenColor=context.tokenColor||game.snapshot().players[0].active?.attribute||settings.tokenTypes[0];
  return choiceCancelled?null:context;
}
async function usePlayerSkill(skillIndex){if(game?.tutorial&&(game.tutorial.stage!==5||skillIndex!==1)){notify("튜토리얼 안내 순서에 따라 진행해 주세요.");return;}const skill=game.snapshot().players[0].active?.skills?.[skillIndex];if(!skill)return;const context=await playerCoinContext(skill.name,skill.effects,skill.description);if(!context)return render();const used=game.useSkill(0,skillIndex,context);if(used&&isPvpMatch())await pvpCommit("skill",{label:skill.name,coinCaption:skill.name,coinResults:pvpCoinResults(context)});if(used&&game.tutorial?.stage===5){game.tutorial.stage=6;completeTutorial();}render();}
function aiBonusDamage(source,e,state){const me=state.players[source],enemy=state.players[1-source];if(e.type==="bonusDamageIfEnemyAttribute"&&enemy.active?.attribute===e.attribute)return e.amount||0;if(e.type==="bonusDamageIfEnemyAttributeExceptName"&&enemy.active?.attribute===e.attribute&&enemy.active?.name!==e.name)return e.amount||0;if(e.type==="bonusDamageIfEnemyAttributeIn"&&e.attributes?.includes(enemy.active?.attribute))return e.amount||0;if(e.type==="bonusDamageIfEnemyAttributeNotIn"&&!e.attributes?.includes(enemy.active?.attribute))return e.amount||0;if(e.type==="bonusDamageUnlessEnemyAttribute"&&enemy.active?.attribute!==e.attribute)return e.amount||0;if(e.type==="bonusDamageUnlessEnemyTag"&&!enemy.active?.tags?.includes(e.tag))return e.amount||0;if(e.type==="bonusDamageIfEnemyName"&&enemy.active?.name===e.name)return e.amount||0;if(e.type==="bonusDamageIfSummonedBy"&&me.active?.summonedBy===e.cardId)return e.amount||0;if(e.type==="bonusDamageIfSelfHpAtLeast"&&me.active?.currentHp>=e.threshold)return e.amount||0;if(e.type==="bonusDamageIfEnemyHpAtMost"&&enemy.active?.currentHp<=e.threshold)return e.amount||0;if(e.type==="bonusDamageIfEnemyHpRatioAtLeast"&&enemy.active?.hp&&enemy.active.currentHp/enemy.active.hp>=e.ratio)return e.amount||0;if(e.type==="bonusDamageIfEnemyTag"&&enemy.active?.tags?.includes(e.tag))return e.amount||0;if(e.type==="bonusDamageForEnemyTag"&&enemy.active?.tags?.includes(e.tag))return e.amount||0;if(e.type==="bonusDamageForActiveCardsWithoutTag")return [me.active,enemy.active].filter(card=>card&&!card.tags?.includes(e.tag)).length*(e.amount||0);if(e.type==="bonusDamageForActiveCardsWithAttribute")return [me.active,enemy.active].filter(card=>card?.attribute===e.attribute).length*(e.amount||0);if(e.type==="bonusDamageIfCharacterUseNumber"&&me.characterUses===e.useNumber)return e.amount||0;if(e.type==="bonusDamageIfEnemyPack"&&enemy.active?.packIds?.includes(e.packId))return e.amount||0;return 0;}
function aiDamageAfterDefense(source,rawDamage,state,{direct=false,strategy=false}={}){const me=state.players[source],enemy=state.players[1-source],target=enemy?.active;if(!target)return {damage:0,blocked:true,risk:0};if(enemy.protectedPackThisTurn?.packId&&target.packIds?.includes(enemy.protectedPackThisTurn.packId))return {damage:0,blocked:true,risk:0};let damage=Math.max(0,rawDamage||0);if(!direct){if(target.weakness===me.active?.attribute)damage*=2;if(target.resistance===me.active?.attribute)damage=Math.max(0,damage-30);if(!strategy)for(const rule of me.damageReductionRulesThisTurn||[])if(rule.tag&&me.active?.tags?.includes(rule.tag))damage=Math.max(0,damage-(rule.amount||0));}const passive=(target.trait?.passive?target.trait.effects||[]:[]).filter(effect=>effect.type==="passiveDamageReduction").reduce((sum,effect)=>sum+(effect.amount||0),0);damage=Math.max(0,damage-(target.permanentDamageReduction||0)-passive);if(!direct&&enemy.reflectDamageThisTurn&&damage>0)return {damage:0,blocked:true,risk:damage};return {damage,blocked:damage<=0,risk:0};}
function estimatedDamage(source,effects,state){let bonus=0,multiplier=1,total=0,defeats=false,risk=0,blockedDamage=false;const me=state.players[source],enemy=state.players[1-source];const apply=(raw,options={})=>{const result=aiDamageAfterDefense(source,raw,state,options);total+=result.damage;risk+=result.risk;blockedDamage=blockedDamage||result.blocked;if(result.damage>=enemy.active.currentHp)defeats=true;};for(const e of effects||[]){if(e.type?.startsWith("bonusDamage")){bonus+=aiBonusDamage(source,e,state);continue;}if(e.type==="guessRandomHandCardAttributeBonus"){bonus+=(e.amount||0)/Math.max(2,settings.tokenTypes.length);continue;}if(e.type==="coinFlipDamageModifier"){multiplier*=((e.headsMultiplier||1)+1)/2;bonus+=((e.headsBonus||0)+(e.tailsBonus||0))/2;continue;}if(e.type==="pushYourLuckDamageModifier"){bonus+=(e.headsBonus||0)/2;continue;}if(e.type==="coinFlipBonusDamageStealTokenOrSelfDamage"){bonus+=(e.headsBonus||0)/2;continue;}if(e.type==="coinFlipsDamageBonusAndSelfDamage"){bonus+=(e.headsBonus||0)*(e.flips||1)/2;continue;}if(e.type==="fixedCoinFlipsDamageBonus"){bonus+=(e.headsBonus||0)*(e.flips||1)/2;continue;}if(e.type==="repeatCoinBonusUntilTails"){bonus+=(e.headsBonus||0);continue;}if(e.type==="streakCoinDamageModifier"){bonus+=Math.max(e.tailsBonus||0,(e.headsBonuses?.[1]||0)/2);continue;}if(e.type==="defeatIfHpAtOrBelow"&&enemy.active?.currentHp<=e.threshold)defeats=true;if(e.type==="directDamage"&&enemy.active){apply(e.amount,{direct:true});continue;}if(e.type==="damageByEnemyTrashCharacters"&&enemy.active){apply((e.amount||0)*(enemy.discard||[]).filter(id=>cardById[id]?.type==="character").length);continue;}if(e.type==="damage"&&enemy.active){apply(((e.amount||0)+bonus)*multiplier);bonus=0;multiplier=1;}}return {damage:total,defeats,risk,blockedDamage};}
function aiCharacterScore(id,state){const card=cardById[id],enemy=state.players[0].active;if(!card||card.type!=="character"||isVmaxCard(card))return -Infinity;let score=card.hp+(RARITIES.length-RARITIES.indexOf(card.rarity))*12;if(enemy){if(card.resistance===enemy.attribute)score+=45;if(card.weakness===enemy.attribute)score-=65;if(enemy.weakness===card.attribute)score+=55;if(enemy.resistance===card.attribute)score-=35;}const candidate={...clone(card),currentHp:card.hp};score+=(card.skills||[]).reduce((sum,skill)=>sum+(estimatedDamage(1,skill.effects,{...state,players:[state.players[0],{...state.players[1],active:candidate}]}).damage||0),0)/3;if(card.trait&&!card.trait.auto)score+=20;return score;}
function aiPickCharacter(state){const characters=state.players[1].hand.filter(id=>cardById[id]?.type==="character"&&!isVmaxCard(cardById[id]));return characters.sort((a,b)=>aiCharacterScore(b,state)-aiCharacterScore(a,state))[0];}
function aiHasRecoverTarget(state,effect,source=1){const player=state.players[source];return (player.discard||[]).some(id=>{const c=cardById[id];return c?.type==="character"&&(!effect.attribute||c.attribute===effect.attribute)&&(!effect.name||c.name===effect.name)&&(!effect.cardId||id===effect.cardId);});}
function aiHasShieldTarget(state,effect,source=1){const active=state.players[source]?.active;return !!(active&&effect?.packId&&active.packIds?.includes(effect.packId));}
function aiEffectUtilityScore(e,state,source=1){const me=state.players[source],enemy=state.players[1-source],enemyTokens=settings.tokenTypes.reduce((sum,c)=>sum+(enemy.tokens?.[c]||0),0);if(e.type==="skipEnemyNextTokenGain")return 30;if(e.type==="increaseEnemyActionCostNextTurn")return 35;if(e.type==="stealEnemyTopDeckCard")return enemy.deck?.length?25:-50;if(e.type==="nextAttackDamageMultiplierThisTurn")return me.active?.skills?.some(skill=>game.canUseSkill(me,skill.cost))?60:-40;if(e.type==="addPermanentDamageReduction")return me.active?30:-50;if(e.type==="reflectNextOpponentDamage")return me.active?45:-50;if(e.type==="reflectPreviousOpponentDamage")return (me.previousOpponentAttackDamage||0)>0&&enemy.active?(me.previousOpponentAttackDamage||0)+25:-80;if(e.type==="healIfSelfTag")return me.active?.tags?.includes(e.tag)&&me.active.currentHp<me.active.hp?Math.min(e.amount||0,me.active.hp-me.active.currentHp):0;if(e.type==="discardAnyHandCardThenDefeatEnemy")return me.hand?.length&&enemy.active?enemy.active.currentHp+250:-100;if(e.type==="suspendEnemyTokens")return enemyTokens?enemyTokens*12:-60;if(e.type==="spyTwoEnemyCardsStealOneAndReplace")return enemy.hand?.length?45:-60;if(e.type==="increaseMaxHp")return me.active?25:-50;return 0;}
function aiActionScore(action,state){const ai=state.players[1],me=state.players[0];if(action.type==="evolve"){const card=cardById[action.id];return (card?.hp||0)+120;}if(action.type==="trait"){const estimate=estimatedDamage(1,ai.active.trait.effects,state);let score=(estimate.defeats?10000:0)+estimate.damage;if((ai.active.trait.effects||[]).some(e=>e.type==="heal"))score+=35;if((ai.active.trait.effects||[]).some(e=>e.type==="nextTurnSkillDamageBonusIfEnemyAttribute"))score+=25;return score;}if(action.type==="skill"){const effects=action.skill.effects||[],estimate=estimatedDamage(1,effects,state),hasDamage=effects.some(e=>["damage","directDamage","damageByEnemyTrashCharacters"].includes(e.type));if(hasDamage&&estimate.blockedDamage&&estimate.damage<=0)return -500-Math.max(0,estimate.risk||0);let score=(estimate.defeats?10000:0)+estimate.damage-(estimate.risk||0)*2;if(effects.some(e=>e.overflowToReplacement))score+=20;if(effects.some(e=>e.type==="requiresStrategyInHand"))score+=15;if(effects.some(e=>e.type==="increaseEnemySkillCostNextTurn"))score+=35;if(effects.some(e=>e.type==="defeatEnemyAndSelf"))score+=me.active?me.active.currentHp+200:0;return score;}if(action.type==="strategy"){const effects=action.card.choices?.flatMap(c=>c.effects||[])||action.card.effects||action.card.trait?.effects||[],estimate=estimatedDamage(1,effects,state);let score=(estimate.defeats?10000:0)+estimate.damage-(estimate.risk||0)*2+effects.reduce((sum,e)=>sum+aiEffectUtilityScore(e,state,1),0);if(effects.some(e=>e.type==="heal"||e.type==="healIfSelfHpAtMost"))score+=ai.active&&ai.active.currentHp<ai.active.hp?Math.min(50,ai.active.hp-ai.active.currentHp):0;if(effects.some(e=>e.type==="draw"))score+=30;if(effects.some(e=>e.type==="addToken"||e.type==="attachToken"||e.type==="fixedCoinFlipsAllHeadsAddToken"))score+=45;const recoverEffects=effects.filter(e=>e.type==="recoverCharacterFromTrash"||e.type==="recoverCharacterFromTrashToDeck");if(recoverEffects.length)score+=recoverEffects.some(e=>aiHasRecoverTarget(state,e,1))?35:-100;const shieldEffects=effects.filter(e=>e.type==="shieldPackFromOpponentEffectsNextTurn");if(shieldEffects.length)score+=shieldEffects.some(e=>aiHasShieldTarget(state,e,1))?45:-100;if(effects.some(e=>e.type==="playHandCharacterAsStrategyNoCount"))score+=20;if(!me.active)score-=50;return score;}return 0;}
function aiBestAction(state){const ai=state.players[1],enemy=state.players[0],blocked=effects=>effects?.some(e=>(e.type==="cannotUseAgainstName"||e.type==="cannotUseIfEnemyName")&&game.activeMatchesName(enemy.active,e.name)),actions=[];ai.hand.forEach(id=>{if(game.canEvolve(1,id))actions.push({type:"evolve",id});});if(ai.active?.trait&&!ai.active.trait.auto&&!ai.active.trait.passive&&!ai.traitUsedThisTurn&&!blocked(ai.active.trait.effects))actions.push({type:"trait"});(ai.active?.skills||[]).forEach((skill,index)=>{const needsStrategy=skill.effects?.some(e=>e.type==="requiresStrategyInHand");if(!blocked(skill.effects)&&game.canUseSkill(ai,skill.cost)&&(!needsStrategy||ai.hand.some(id=>cardById[id]?.type==="strategy")))actions.push({type:"skill",skill,index});});ai.hand.forEach(id=>{const card=cardById[id],asStrategy=card?.type==="strategy"||card?.trait?.treatAsStrategy;const effects=card?.choices?.flatMap(c=>c.effects||[])||card?.effects||card?.trait?.effects;if(asStrategy&&!blocked(effects))actions.push({type:"strategy",card,id});});const scored=actions.map(action=>({...action,score:aiActionScore(action,state)})).filter(action=>action.score>0);return scored.sort((a,b)=>b.score-a.score)[0];}
function aiShouldUseOptionalCoin(effects=[],state=game?.snapshot(),source=1){
  const baseDamage=(effects.find(e=>e.type==="damage")?.amount)||0;
  return effects.some(e=>{
    if(!effectAppliesToState(e,source,state))return false;
    if(e.type==="coinFlipDamageModifier"){
      const heads=(baseDamage+(e.headsBonus||0))*(e.headsMultiplier||1),tails=baseDamage+(e.tailsBonus||0);
      return (heads+tails)/2>=baseDamage;
    }
    if(e.type==="coinFlipHealSelfOrBonusDamage")return ((e.headsHeal||0)+(e.tailsBonus||0))/2>0;
    if(e.type==="coinFlipBonusDamageStealTokenOrSelfDamage")return (e.headsBonus||0)+(e.headsStealToken||0)*15 >= (e.tailsSelfDamage||0);
    if(e.type==="coinFlipBonusDamageUnlessEnemyAttribute")return (e.headsBonus||0)>0;
    if(e.type==="coinFlipBonusOrSelfDamageIfEnemyAttribute")return (e.headsBonus||0) >= (e.tailsSelfDamage||0);
    if(e.type==="fixedCoinFlipsDamageBonus"||e.type==="fixedCoinFlipsAllHeadsAddToken")return (e.headsBonus||e.amount||0)>0;
    if(e.type==="coinFlipsDamageBonusAndSelfDamage")return (e.headsBonus||0)>0;
    if(e.type==="pushYourLuckDamageModifier")return (e.headsBonus||0)>0&&state.players[source]?.active?.currentHp>(e.tailsSelfDamage||0);
    if(e.type==="repeatCoinBonusUntilTails")return (e.headsBonus||0)>0;
    if(e.type==="streakCoinDamageModifier")return Math.max(...(e.headsBonuses||[0]),e.tailsBonus||0)>0;
    return false;
  });
}
async function aiCoinContext(label,effects,description=""){
  const snapshot=game.snapshot(),context={},player=snapshot.players[1],enemy=snapshot.players[0],forced=player.forceNextCoinHeads?"heads":null,optionalText=optionalWording(description);
  const coinTypes=COIN_EFFECT_TYPES;
  const coinEffects=(effects||[]).filter(e=>coinTypes.includes(e.type)&&effectAppliesToState(e,1,snapshot));
  if((effects||[]).some(e=>e.type==="guessRandomHandCardAttributeBonus")){const hand=enemy.hand||[],pickedIndex=hand.length?Math.floor(Math.random()*hand.length):-1;context.guessedHandId=pickedIndex>=0?hand[pickedIndex]:null;context.guessedAttribute=enemy.active?.attribute||settings.tokenTypes[Math.floor(Math.random()*settings.tokenTypes.length)];if(context.guessedHandId)await showAiChoiceEffect({label,lines:[`상대 손패 ${pickedIndex+1}번 선택`,`속성 ${attributeLabel(context.guessedAttribute)} 예측`]});}
  if((effects||[]).some(e=>e.type==="revealChosenEnemyHand")){const hand=enemy.hand||[],pickedIndex=hand.length?Math.floor(Math.random()*hand.length):-1;context.revealHandId=pickedIndex>=0?hand[pickedIndex]:null;if(context.revealHandId)await showAiChoiceEffect({label,lines:[`상대 손패 ${pickedIndex+1}번 확인`]});}
  if((effects||[]).some(e=>e.type==="stealToken")){context.stealColor=bestAvailableToken(enemy.tokens);if(context.stealColor)await showAiChoiceEffect({label,lines:[`${attributeLabel(context.stealColor)} 토큰 선택`]});}
  if((effects||[]).some(e=>e.type==="discardAnyHandCardThenDefeatEnemy"||e.type==="discardPreferredHandCardForBonusDamage"))context.discardHandId=player.hand[0]||null;
  if((effects||[]).some(e=>e.type==="swapHandCardWithEnemy")){context.ownHandId=player.hand[0]||null;context.enemyHandId=enemy.hand[0]||null;}
  if((effects||[]).some(e=>e.type==="spyTwoEnemyCardsStealOneAndReplace")){const seen=enemy.hand.slice(0,2);context.stealHandId=seen.sort((a,b)=>RARITIES.indexOf(cardById[a]?.rarity)-RARITIES.indexOf(cardById[b]?.rarity))[0]||null;}
  const convertEffect=(effects||[]).find(e=>e.type==="convertEnemyToken");
  if(convertEffect){context.convertEnemyColor=bestAvailableToken(enemy.tokens,convertEffect.to);if(context.convertEnemyColor)await showAiChoiceEffect({label,lines:[`${attributeLabel(context.convertEnemyColor)} 토큰 변환 선택`]});}
  const playHandEffect=(effects||[]).find(e=>e.type==="playHandCharacterAsStrategyNoCount");
  if(playHandEffect){
    const candidates=(player.hand||[]).filter(id=>{const c=cardById[id];return c?.type==="character"&&!isVmaxCard(c)&&id!==playHandEffect.excludeCardId&&(!playHandEffect.cardId||id===playHandEffect.cardId)&&(!playHandEffect.name||c.name===playHandEffect.name);});
    context.handCharacterId=candidates.sort((a,b)=>aiCharacterScore(b,snapshot)-aiCharacterScore(a,snapshot))[0]||null;
    if(context.handCharacterId)await showAiChoiceEffect({label,lines:[`${cardById[context.handCharacterId]?.name||context.handCharacterId} 배치 선택`]});
  }
  const recoverEffect=(effects||[]).find(e=>e.type==="recoverCharacterFromTrash"||e.type==="recoverCharacterFromTrashToDeck");
  if(recoverEffect){
    const candidates=(player.discard||[]).filter(id=>{const c=cardById[id];return c?.type==="character"&&(!recoverEffect.attribute||c.attribute===recoverEffect.attribute)&&(!recoverEffect.name||c.name===recoverEffect.name)&&(!recoverEffect.cardId||id===recoverEffect.cardId);});
    context.trashCharacterId=candidates.sort((a,b)=>RARITIES.indexOf(cardById[a].rarity)-RARITIES.indexOf(cardById[b].rarity))[0]||null;
    if(context.trashCharacterId)await showAiChoiceEffect({label,lines:[`${cardById[context.trashCharacterId]?.name||context.trashCharacterId} 회수 선택`]});
  }
  const needsTokenColor=(effects||[]).some(e=>e.type==="gainTokenIfDefeats"||e.type==="convertOwnTokenToActiveAttribute"||e.type==="convertOwnTokenToChosenColor"||e.type==="convertAllEnemyTokensByColor"||e.type==="changeSelfAttribute"||((e.type==="addToken"||e.type==="attachToken")&&e.color==="any"));
  context.tokenColor=aiBestToken(game.snapshot());
  if(needsTokenColor)await showAiChoiceEffect({label,lines:[`${attributeLabel(context.tokenColor)} 토큰 선택`]});
  if((effects||[]).some(e=>e.type==="discardOwnTokensDrawThenDiscardHandBonusDamage"&&e.optional))context.skipOptionalTrade=(player.tokens.brown||0)<=0||player.hand.length>3;
  if((effects||[]).some(e=>e.type==="optionalDefeatSelfForBonusDamage"))context.defeatSelfForBonus=enemy.active?.currentHp<=160;
  const hasOptionalCoin=coinEffects.some(e=>e.optional||optionalText);
  if(hasOptionalCoin){
    context.optionalText=optionalText;
    if(aiShouldUseOptionalCoin(effects,snapshot,1)){await showAiChoiceEffect({label,lines:["동전 뒤집기 선택"]});game.emit(`AI가 「${label}」의 동전 뒤집기 효과를 선택했습니다.`);}
    else{context.skipOptionalCoinFlip=true;game.emit(`AI가 「${label}」의 동전 뒤집기 효과를 선택하지 않았습니다.`);}
  }
  for(const e of effects||[]){
    if(coinTypes.includes(e.type)&&!effectAppliesToState(e,1,snapshot))continue;
    if(context.skipOptionalCoinFlip&&(e.optional||context.optionalText)&&coinTypes.includes(e.type))continue;
    if(e.type==="coinFlipDamageModifier"||e.type==="coinFlipSelfDamageOnTails"||e.type==="coinFlipHealSelfOrBonusDamage"){
      context.coinResult=await showCoinFlip({caption:`AI: ${label}`,headsLabel:"앞면",tailsLabel:"뒷면",result:forced||undefined});
      break;
    }
    if(e.type==="fixedCoinFlipsDamageBonus"||e.type==="fixedCoinFlipsAllHeadsAddToken"||e.type==="coinFlipAddTokensByResult"){
      context.coinResults=[];
      for(let i=0;i<(e.flips||1);i++)context.coinResults.push(await showCoinFlip({caption:`AI: ${label} ${i+1}/${e.flips||1}`,headsLabel:"앞면",tailsLabel:"뒷면",result:forced&&i===0?forced:undefined}));
      break;
    }
    if(e.type==="coinFlipsDamageBonusAndSelfDamage"){
      context.coinResults=[];
      for(let i=0;i<(e.flips||1);i++)context.coinResults.push(await showCoinFlip({caption:`AI: ${label} ${i+1}/${e.flips||1}`,headsLabel:"앞면",tailsLabel:"뒷면",result:forced&&i===0?forced:undefined}));
      break;
    }
    if(e.type==="pushYourLuckDamageModifier"){
      context.coinResults=[];
      let result="heads",guard=0,max=e.maxFlips||8;
      while(result==="heads"&&guard<max){
        result=await showCoinFlip({caption:`AI: ${label} ${guard+1}/${max}`,headsLabel:"앞면",tailsLabel:"뒷면",result:forced&&guard===0?forced:undefined});
        context.coinResults.push(result);
        guard++;
        if(result==="heads"){
          const projected=(effects.find(x=>x.type==="damage")?.amount||0)+guard*(e.headsBonus||0);
          if(enemy.active?.currentHp<=projected||player.active?.currentHp<=(e.tailsSelfDamage||0)+20||Math.random()>.35)break;
        }
      }
      break;
    }
    if(e.type==="repeatCoinBonusUntilTails"){
      context.coinResults=await showCoinSeries({caption:`AI: ${label}`,maxFlips:e.maxFlips||8,forced});
      break;
    }
    if(e.type==="streakCoinDamageModifier"){
      context.coinResults=await showCoinSeries({caption:`AI: ${label}`,maxFlips:e.maxFlips||e.headsBonuses?.length||3,forced});
      break;
    }
    if(e.type==="coinFlipBonusDamageStealTokenOrSelfDamage"||e.type==="coinFlipBonusDamageUnlessEnemyAttribute"||e.type==="coinFlipBonusOrSelfDamageIfEnemyAttribute"||e.type==="recoverThisStrategyOnCoinHeads"||e.type==="coinFlipStealToken"||e.type==="coinFlipBonusDamageOrHealEnemy"){
      context.coinResult=await showCoinFlip({caption:`AI: ${label}`,headsLabel:"앞면",tailsLabel:"뒷면",result:forced||undefined});
      break;
    }
  }
  return context;
}
function aiBestToken(state){const ai=state.players[1],skills=ai.active?.skills||[],needScores={};settings.tokenTypes.forEach(c=>needScores[c]=0);skills.forEach(skill=>{const estimate=estimatedDamage(1,skill.effects,state),specific=Object.entries(skill.cost||{}).filter(([c])=>c!=="any"),weight=(estimate.defeats?80:estimate.damage)+20;specific.forEach(([color,n])=>{if((ai.tokens[color]||0)<n)needScores[color]+=weight*(n-(ai.tokens[color]||0));});});const best=Object.entries(needScores).sort((a,b)=>b[1]-a[1])[0];if(best&&best[1]>0)return best[0];const activeColor=ai.active?.attribute;if(activeColor&&settings.tokenTypes.includes(activeColor))return activeColor;return settings.tokenTypes[Math.floor(Math.random()*settings.tokenTypes.length)];}
function aiChooseStrategyChoice(card,state){if(!card?.choices?.length)return null;const ai=state.players[1];let bestIndex=0,bestScore=-Infinity;card.choices.forEach((choice,index)=>{let score=estimatedDamage(1,choice.effects,state).damage;for(const e of choice.effects||[]){if(e.type==="attachToken"||e.type==="addToken")score+=(e.amount||1)*20;if(e.type==="recoverCharacterFromTrash"||e.type==="recoverCharacterFromTrashToDeck"){const has=(ai.discard||[]).some(id=>{const c=cardById[id];return c?.type==="character"&&(!e.attribute||c.attribute===e.attribute)&&(!e.name||c.name===e.name)&&(!e.cardId||id===e.cardId);});if(has)score+=80;}if(e.type==="shieldPackFromOpponentEffectsNextTurn")score+=aiHasShieldTarget(state,e,1)?45:-100;}if(score>bestScore){bestScore=score;bestIndex=index;}});return bestIndex;}
async function aiStep(){
  if(!game)return;
  if(game.tutorial){const tutorialState=game.snapshot();if(tutorialState.turn===1){game.endTurn(1,"blue");if(game.tutorial.stage===1){game.tutorial.stage=2;game.emit("튜토리얼: 윤석열 VMAX로 진화해 보세요.");}else if(game.tutorial.stage===3){game.tutorial.stage=4;game.emit("튜토리얼: 빨강 토큰을 받았습니다. 이제 전략 카드를 사용해 보세요.");}render();}return;}
  const s=game.snapshot(),ai=s.players[1];
  if(s.phase==="playing"&&s.turn===1&&ai.active?.faceDown){const result=await showCoinFlip({caption:"뒷면 카드 활성화",result:Math.random()<.5?"heads":"tails"});game.flipFaceDownActive(1,{coinResult:result,tokenColor:aiBestToken(s)});render();setTimeout(aiStep,650);return;}
  if(s.phase==="choose-active"&&s.first===1&&!s.initialAIDone){
    const id=aiPickCharacter(s);
    if(id){game.chooseActive(1,id);game.state.initialAIDone=true;game.state.phase="setup-bonus";game.emit("후공 플레이어는 시작 보너스를 사용합니다.");}
    else game.loseIfNoPlayableCharacter(1);
    return;
  }
  if(s.phase==="choose-replacement"&&s.turn===1){
    const id=aiPickCharacter(s);
    if(id){game.completeForcedReplacement(1,id);setTimeout(()=>{game.endTurn(1,aiBestToken(game.snapshot()));},350)}
    else game.end(0);
    return;
  }
  if(s.phase!=="playing"||s.turn!==1)return;
  if(!s.actionAvailable){
    if(ai.traitAfterSkillAvailable&&ai.active?.trait&&!ai.active.trait.auto&&!ai.active.trait.passive&&!ai.traitUsedThisTurn){
      const trait=ai.active.trait,context=await aiCoinContext(trait.name,trait.effects,trait.description||"");
      game.useTrait(1,context);
      setTimeout(aiStep,650);
      return;
    }
    game.endTurn(1,aiBestToken(s));setTimeout(aiStep,650);return;
  }
  const action=aiBestAction(s);
  if(action?.type==="evolve"){
    game.evolveActive(1,action.id);
  }else if(action?.type==="trait"){
    const trait=ai.active.trait,context=await aiCoinContext(trait.name,trait.effects,trait.description||"");
    game.useTrait(1,context);
  }else if(action?.type==="skill"){
    const context=await aiCoinContext(action.skill.name,action.skill.effects,action.skill.description||"");
    game.useSkill(1,action.index,context);
  }else if(action?.type==="strategy"){
    const choiceIndex=aiChooseStrategyChoice(action.card,game.snapshot()),choice=choiceIndex==null?null:action.card.choices?.[choiceIndex],effects=choice?.effects||action.card.effects||action.card.trait?.effects||[],description=choice?.description||action.card.description||action.card.trait?.description||"";
    const context=await aiCoinContext(action.card.name,effects,description);
    if(effects.some(e=>e.type==="discardAnyHandCardThenDefeatEnemy"))context.discardHandId=game.snapshot().players[1].hand.find(id=>id!==action.id)||null;
    if(choiceIndex!=null)context.choiceIndex=choiceIndex;
    game.useStrategy(1,action.id,context);
  }else game.endTurn(1,aiBestToken(s));
  setTimeout(aiStep,650);
}
async function startGame(opponentId=selectedAiOpponentId){unlockAudio();if(!validDeck(profile.deck)){notify(deckLimitMessage());go("deck");return;}selectedAiOpponentId=opponentId;const opponent=selectedAiOpponent(),opponentDeck=buildAiDeck(opponent);route="game";location.hash="game";game=new GameEngine(profile.deck,()=>{if(route==="game")render();},opponentDeck);game.aiOpponent=opponent;syncRouteMusic({restart:true});render();const first=Math.random()<.5?0:1;await showCoinFlip({caption:"선공 결정",headsLabel:"나 선공",tailsLabel:"AI 선공",result:first===0?"heads":"tails"});game.setup(first);if(first===0)game.loseIfNoPlayableCharacter(0);render();if(game.snapshot().first===1)setTimeout(aiStep,650);}
function openPostModal(){if(!needLogin())return;modal(`<h3>갤러리 글쓰기</h3><form id="gallery-post-form" class="post-form"><label>제목<input name="title" required maxlength="80" placeholder="제목을 입력하세요"></label><label>내용<textarea name="body" required maxlength="5000" rows="9" placeholder="내용을 입력하세요"></textarea></label><button class="btn primary">등록</button></form>`);document.querySelector("#gallery-post-form").onsubmit=async event=>{event.preventDefault();const form=new FormData(event.currentTarget);try{const post=await window.politimonBackend.createPost(String(form.get("title")).trim(),String(form.get("body")).trim(),currentUser());galleryPosts.unshift(post);galleryLoaded=true;selectedGalleryPostId=post.id;modalRoot.innerHTML="";render();notify("글을 등록했습니다.");}catch(error){notify(`등록하지 못했습니다: ${error.message}`);}};}
function openCreateRoomModal(){if(!needLogin())return;if(!validDeck(profile.deck)){notify(deckLimitMessage());go("deck");return;}modal(`<h3>방 만들기</h3><form id="create-room-form" class="post-form"><label>방 제목<input name="title" required maxlength="40" placeholder="예: 주말 한 판"></label><label class="privacy-check"><input name="private" type="checkbox"> 비공개 방 (4자리 비밀번호 사용)</label><label id="room-password-field" hidden>비밀번호<input name="password" inputmode="numeric" pattern="[0-9]{4}" minlength="4" maxlength="4" placeholder="숫자 4자리"></label><button class="btn primary">방 만들기</button></form>`);const form=document.querySelector("#create-room-form"),check=form.querySelector("[name=private]"),field=document.querySelector("#room-password-field");check.onchange=()=>field.hidden=!check.checked;form.onsubmit=async event=>{event.preventDefault();const value=new FormData(form),isPrivate=check.checked,password=String(value.get("password")||"");if(isPrivate&&!/^\d{4}$/.test(password))return notify("비공개 방 비밀번호는 숫자 4자리여야 합니다.");try{activeRoom=await window.politimonBackend.createRoom({title:String(value.get("title")).trim(),isPrivate,password},currentUser());activeRoom=await registerRoomDeck(activeRoom);watchPvpRoom(activeRoom.id);modalRoot.innerHTML="";render();}catch(error){notify(`방을 만들지 못했습니다: ${error.message}`);}};}
function openJoinRoomModal(room){if(!needLogin())return;if(!validDeck(profile.deck)){notify(deckLimitMessage());go("deck");return;}const join=async password=>{try{activeRoom=await window.politimonBackend.joinRoom(room.id,password,currentUser());activeRoom=await registerRoomDeck(activeRoom);watchPvpRoom(activeRoom.id);modalRoot.innerHTML="";render();}catch(error){notify(`입장하지 못했습니다: ${error.message}`);}};if(!room.is_private)return join("");modal(`<h3>${escape(room.title)} 입장</h3><form id="join-room-form" class="post-form"><label>4자리 비밀번호<input name="password" required inputmode="numeric" pattern="[0-9]{4}" minlength="4" maxlength="4" placeholder="0000"></label><button class="btn primary">입장</button></form>`);document.querySelector("#join-room-form").onsubmit=event=>{event.preventDefault();join(new FormData(event.currentTarget).get("password"));};}
function bind(){document.querySelector("#signin-form")?.addEventListener("submit",async event=>{event.preventDefault();const form=new FormData(event.currentTarget);try{const result=await window.politimonBackend.signIn(String(form.get("email")),String(form.get("password")));authSession=result?.user?{user:result.user}:result;await syncDeveloperAccess();render();notify("로그인했습니다.");}catch(error){notify(`로그인하지 못했습니다: ${error.message}`);}});document.querySelector("#signup-form")?.addEventListener("submit",async event=>{event.preventDefault();const form=new FormData(event.currentTarget);try{const result=await window.politimonBackend.signUp(String(form.get("email")),String(form.get("password")),String(form.get("displayName")));authSession=result.session||null;if(result.needsEmailConfirmation)notify("인증 이메일을 확인한 뒤 로그인해 주세요.");else{await syncDeveloperAccess();render();notify("계정을 만들었습니다.");}}catch(error){notify(`가입하지 못했습니다: ${error.message}`);}});document.querySelector("#signout")?.addEventListener("click",async()=>{try{await window.politimonBackend.signOut();authSession=null;isDeveloper=false;activeRoom=null;render();notify("로그아웃했습니다.");}catch(error){notify(error.message);}});document.querySelector("#gallery-write")?.addEventListener("click",openPostModal);document.querySelectorAll("[data-gallery-post]").forEach(button=>button.onclick=()=>{selectedGalleryPostId=button.dataset.galleryPost;render();});document.querySelector("#create-room")?.addEventListener("click",openCreateRoomModal);document.querySelector("#refresh-rooms")?.addEventListener("click",()=>loadRooms({force:true}));document.querySelectorAll("[data-join-room]").forEach(button=>button.onclick=()=>openJoinRoomModal(multiplayerRooms.find(room=>room.id===button.dataset.joinRoom)));document.querySelector("#room-ready")?.addEventListener("click",async()=>{try{activeRoom=await window.politimonBackend.setReady(activeRoom.id,!activeRoom.members.find(member=>member.user_id===currentUser().id)?.ready);render();}catch(error){notify(error.message);}});document.querySelector("#room-start")?.addEventListener("click",async()=>{try{await window.politimonBackend.startRoom(activeRoom.id);notify("게임 시작을 확정했습니다. 배포 전 안내의 match-action 함수까지 올리면 전투 행동도 상대와 동기화됩니다.");}catch(error){notify(error.message);}});document.querySelector("#leave-room")?.addEventListener("click",()=>{activeRoom=null;roomsLoaded=false;render();});document.querySelectorAll("[data-route]").forEach(b=>b.onclick=()=>go(b.dataset.route));document.querySelector("#global-back")?.addEventListener("click",goBack);document.querySelectorAll("[data-card-detail],[data-card-info],[data-hand-card]").forEach(el=>el.onclick=e=>{e.stopPropagation();cardDetail(el.dataset.cardDetail||el.dataset.cardInfo||el.dataset.handCard);});document.querySelectorAll("[data-rarity-filter]").forEach(b=>b.onclick=()=>{collectionFilter=b.dataset.rarityFilter;render();});document.querySelectorAll("[data-guide-tab]").forEach(b=>b.onclick=()=>{guideTab=b.dataset.guideTab;render();});document.querySelector("#collection-search")?.addEventListener("input",e=>{collectionSearch=e.target.value;render();});document.querySelector("#start-game")?.addEventListener("click",()=>startGame(selectedAiOpponentId));document.querySelectorAll("[data-ai-opponent]").forEach(b=>b.onclick=()=>{selectedAiOpponentId=b.dataset.aiOpponent;render();});document.querySelector("#reset-profile")?.addEventListener("click",()=>modal(`<h3>진행 상황 초기화</h3><p>재화, 카드 보유, 덱, 전적, 도전과제를 초기 상태로 되돌립니다. 기본 재화는 250P입니다.</p><button class="btn primary" id="confirm-reset-profile">초기화 실행</button>`));document.querySelector("#confirm-reset-profile")?.addEventListener("click",()=>{profile=resetProfile();game=null;modalRoot.innerHTML="";render();notify("초기화 완료: 기본 재화 250P 지급");});document.querySelector("#reset-deck")?.addEventListener("click",()=>{profile.deck=resetProfile().deck;profile.collection=Object.fromEntries(Object.entries(profile.collection).map(([id,count])=>[id,count>0?1:0]));save();render();notify("기본 덱을 복원했습니다.");});document.querySelectorAll("[data-add-card]").forEach(b=>b.onclick=()=>{const card=cardById[b.dataset.addCard],counts=deckCounts(profile.deck);if(profile.deck.includes(card.id))return notify("같은 카드는 덱에 1장만 넣을 수 있습니다.");if(profile.deck.length>=settings.deckCardCount)return notify("덱은 총 10장으로 고정됩니다.");if(card.type==="character"&&counts.characters>=settings.characterLimit)return notify("인물 카드는 7장까지입니다.");if(card.type==="strategy"&&counts.strategies>=settings.strategyLimit)return notify("전략 카드는 3장까지입니다.");if(isVmaxCard(card)&&counts.vmax>=(settings.vmaxLimit??2))return notify(`VMAX 카드는 ${settings.vmaxLimit??2}장까지입니다.`);if(card.rarity==="SSR"&&counts.ssr>=(settings.ssrLimit??2))return notify(`SSR 카드는 ${settings.ssrLimit??2}장까지입니다.`);profile.deck.push(b.dataset.addCard);save();render();});document.querySelectorAll("[data-remove-index]").forEach(b=>b.onclick=()=>{profile.deck.splice(Number(b.dataset.removeIndex),1);save();render();});document.querySelectorAll("[data-remove-card]").forEach(b=>b.onclick=e=>{e.stopPropagation();const index=profile.deck.indexOf(b.dataset.removeCard);if(index>=0){profile.deck.splice(index,1);save();render();}});document.querySelectorAll("[data-pack-detail]").forEach(b=>b.onclick=e=>{e.stopPropagation();const pack=packs.find(p=>p.id===b.dataset.packDetail);if(pack)modal(packSummary(pack));});document.querySelectorAll("[data-pack-info]").forEach(el=>el.onclick=e=>{if(e.target.closest("button"))return;const pack=packs.find(p=>p.id===el.dataset.packInfo);if(pack)modal(packSummary(pack));});document.querySelectorAll("[data-open-pack]").forEach(b=>b.onclick=e=>{e.stopPropagation();openPack(b.dataset.openPack);});
 document.querySelector("#inspect-top")?.addEventListener("click",()=>{const id=game.inspectSecondPlayerTop();const s=game.snapshot();modal(`<h3>후공 보너스</h3><p>덱 맨 위 카드</p>${id?`<div class="choice-cards">${choiceCard(id,"data-card-info")}</div>`:"<p>덱이 비어 있습니다.</p>"}<p>아래의 손패 카드와 교환하거나 그대로 진행하세요.</p><div class="swap-cards">${s.players[0].hand.map(id=>choiceCard(id,"data-swap")).join("")}</div><button class="btn primary" id="bonus-continue">그대로 진행</button>`);keepModalOpenOnClose();document.querySelectorAll("[data-card-info]").forEach(b=>b.onclick=e=>{e.stopPropagation();cardDetail(b.dataset.cardInfo);});document.querySelectorAll("[data-swap]").forEach(b=>b.onclick=()=>{game.swapSecondPlayerTop(b.dataset.swap);modalRoot.innerHTML="";game.state.phase="choose-active";if(!game.loseIfNoPlayableCharacter(0))render();});document.querySelector("#bonus-continue").onclick=()=>{modalRoot.innerHTML="";game.state.phase="choose-active";if(!game.loseIfNoPlayableCharacter(0))render();};});document.querySelector("#skip-bonus")?.addEventListener("click",()=>{game.state.phase="choose-active";if(!game.loseIfNoPlayableCharacter(0))render();});
 document.querySelectorAll("[data-play-character]").forEach(b=>b.onclick=()=>{const s=game.snapshot();if(isPvpMatch()){const used=s.phase==="choose-active"?pvpChooseActive(b.dataset.playCharacter):s.players[0].forcedReplacement?game.completeForcedReplacement(0,b.dataset.playCharacter):game.chooseActive(0,b.dataset.playCharacter,{replacement:s.phase==="choose-replacement"});if(used&&s.phase!=="choose-active")pvpCommit("choose-replacement");render();return;}const forced=s.players[0].forcedReplacement;if(forced)game.completeForcedReplacement(0,b.dataset.playCharacter);else game.chooseActive(0,b.dataset.playCharacter,{replacement:s.phase==="choose-replacement"});if(s.phase==="choose-active"){if(s.initialAIDone){game.state.phase="playing";game.state.actionAvailable=true;}else{const aiId=aiPickCharacter(game.snapshot());if(aiId)game.chooseActive(1,aiId);game.state.phase="playing";game.state.actionAvailable=true;}}render();if(game.snapshot().turn===1)setTimeout(aiStep,1200);});
 document.querySelector("#trait-btn")?.addEventListener("click",async()=>{if(game?.tutorial&&game.tutorial.stage!==0)return notify("튜토리얼 안내 순서에 따라 진행해 주세요.");const trait=game.snapshot().players[0].active?.trait;if(!trait)return;const context=await playerCoinContext(trait.name,trait.effects,trait.description);if(!context)return render();if(!game.useTrait(0,context))notify("특성을 사용할 수 없습니다.");else{if(isPvpMatch())await pvpCommit("trait",{label:trait.name,coinCaption:trait.name,coinResults:pvpCoinResults(context)});if(game.tutorial?.stage===0){game.tutorial.stage=1;game.emit("특성을 사용했습니다. 이제 빨강 토큰을 선택해 턴을 종료하세요.");}}render();});
 document.querySelectorAll("[data-use-skill-direct]").forEach(b=>b.onclick=()=>usePlayerSkill(Number(b.dataset.useSkillDirect)));
 document.querySelector("#skill-btn")?.addEventListener("click",()=>{const s=game.snapshot(),skills=s.players[0].active?.skills||[];modal(`<h3>기술 선택</h3><div class="skill-list">${skills.map((x,i)=>`<button data-use-skill="${i}" ${!canUseSkill(s.players[0],x)?"disabled":""}><b>${x.name}</b><span>${costDots(x.cost)}</span><small>${x.description}</small></button>`).join("")}</div>`);document.querySelectorAll("[data-use-skill]").forEach(b=>b.onclick=async()=>{modalRoot.innerHTML="";await usePlayerSkill(Number(b.dataset.useSkill));});});
 document.querySelector("#evolve-btn")?.addEventListener("click",()=>{if(game?.tutorial&&game.tutorial.stage!==2)return notify("튜토리얼 안내 순서에 따라 진행해 주세요.");const ids=game.snapshot().players[0].hand.filter(id=>game.canEvolve(0,id));modal(`<h3>진화할 카드 선택</h3><p>VMAX는 대응 V 카드 위에만 내려놓을 수 있습니다.</p><div class="choice-cards">${ids.map(id=>choiceCard(id,"data-evolve-character")).join("")||"<p>진화 가능한 카드가 없습니다.</p>"}</div>`);document.querySelectorAll("[data-evolve-character]").forEach(b=>b.onclick=()=>{modalRoot.innerHTML="";if(!game.evolveActive(0,b.dataset.evolveCharacter))notify("진화할 수 없습니다.");else{if(isPvpMatch())pvpCommit("evolve");if(game.tutorial?.stage===2){game.tutorial.stage=3;game.emit("윤석열 VMAX 진화 완료. 다시 빨강 토큰을 받아 턴을 넘기세요.");}}render();});});
 document.querySelector("#retreat-btn")?.addEventListener("click",()=>{const used=game.retreat(0);if(used&&isPvpMatch())pvpCommit("retreat");render();});
 document.querySelector("#strategy-btn")?.addEventListener("click",()=>{if(game?.tutorial&&game.tutorial.stage!==4)return notify("튜토리얼 안내 순서에 따라 진행해 주세요.");choiceCancelled=false;const hand=game.snapshot().players[0].hand.filter(id=>cardById[id].type==="strategy"||cardById[id].trait?.treatAsStrategy);modal(`<h3>전략 카드 선택</h3><div class="choice-cards">${hand.map(id=>choiceCard(id,"data-use-strategy")).join("")||"<p>사용 가능한 전략 카드가 없습니다.</p>"}</div>`);document.querySelectorAll("[data-use-strategy]").forEach(b=>b.onclick=async()=>{const card=cardById[b.dataset.useStrategy];modalRoot.innerHTML="";const selected=await chooseStrategyChoice(card);if(!selected)return render();const context=await playerCoinContext(card?.name||"전략",selected.effects||[],selected.description||card?.description||card?.trait?.description||"",b.dataset.useStrategy);if(!context)return render();context.choiceIndex=selected.index;if(!game.useStrategy(0,b.dataset.useStrategy,context))notify("전략 카드를 사용할 수 없습니다.");else{if(isPvpMatch())await pvpCommit("strategy",{label:selected.index==null?card.name:`${card.name} · ${card.choices[selected.index]?.label||"효과"}`,coinCaption:card.name,coinResults:pvpCoinResults(context)});if(game.tutorial?.stage===4){game.tutorial.stage=5;game.emit("전략 카드 사용 완료. 윤석열 VMAX의 두 번째 기술을 사용하세요.");}}render();});});
 document.querySelectorAll("[data-end-turn]").forEach(b=>b.onclick=async()=>{if(game?.tutorial&&![1,3].includes(game.tutorial.stage))return notify("튜토리얼 안내 순서에 따라 진행해 주세요.");choiceCancelled=false;const s=game.snapshot(),extra=s.players[0].extraTokensThisTurn||0,extraColors=[];for(let i=0;i<extra;i++)extraColors.push(await chooseToken({caption:`추가 토큰 ${i+1}/${extra} 선택`}));if(choiceCancelled||!game.endTurn(0,b.dataset.endTurn,extraColors))return render();if(isPvpMatch())await pvpCommit("end-turn");render();if(!isPvpMatch())setTimeout(aiStep,1200);});
 document.querySelector("#face-down-coin")?.addEventListener("click",async()=>{const result=await showCoinFlip({caption:"뒷면 카드 활성화",result:Math.random()<.5?"heads":"tails"});const used=game.flipFaceDownActive(0,{coinResult:result});if(used!=null&&isPvpMatch())await pvpCommit("face-down",{label:"뒷면 카드 활성화",coinCaption:"뒷면 카드 활성화",coinResults:[result]});render();if(!isPvpMatch())setTimeout(aiStep,1200);});
 document.querySelector("#return-home")?.addEventListener("click",()=>go("home"));
 const resetDeckButton=document.querySelector("#reset-deck");if(resetDeckButton)resetDeckButton.onclick=()=>{profile.deck=[...STARTER_DECK].filter(id=>cardById[id]&&(profile.collection[id]||0)>0);save();render();notify("기본 덱을 복원했습니다.");};
}
