document.addEventListener("click",e=>{const info=e.target?.closest?.("[data-card-info]");if(info){e.stopPropagation();cardDetail(info.dataset.cardInfo);return;}const packFilter=e.target?.closest?.("[data-pack-filter]");if(packFilter){collectionPackFilter=packFilter.dataset.packFilter;render();return;}const attributeFilter=e.target?.closest?.("[data-attribute-filter]");if(attributeFilter){collectionAttributeFilter=attributeFilter.dataset.attributeFilter;render();return;}const deckRarityFilter=e.target?.closest?.("[data-deck-rarity-filter]");if(deckRarityFilter){deckFilter=deckRarityFilter.dataset.deckRarityFilter;render();return;}const deckPackFilterButton=e.target?.closest?.("[data-deck-pack-filter]");if(deckPackFilterButton){deckPackFilter=deckPackFilterButton.dataset.deckPackFilter;render();return;}const deckAttributeFilterButton=e.target?.closest?.("[data-deck-attribute-filter]");if(deckAttributeFilterButton){deckAttributeFilter=deckAttributeFilterButton.dataset.deckAttributeFilter;render();return;}if(e.target?.id==="confirm-reset-profile"){profile=resetProfile();game=null;modalRoot.innerHTML="";render();notify("초기화 완료: 기본 재화 250P 지급");return;}});
document.addEventListener("click",e=>{const button=e.target?.closest?.("[data-achievement-category]");if(!button)return;achievementCategory=button.dataset.achievementCategory||"ALL";render();});
document.addEventListener("input",e=>{if(e.target?.id==="collection-search"||e.target?.id==="deck-search")e.stopImmediatePropagation();},true);
document.addEventListener("keydown",e=>{if(e.key!=="Enter")return;if(e.target?.id==="collection-search"){e.preventDefault();collectionSearch=e.target.value;render();}if(e.target?.id==="deck-search"){e.preventDefault();deckSearch=e.target.value;render();}});
document.addEventListener("click",e=>{const search=e.target?.closest?.("[data-search-apply]");if(!search)return;const input=document.querySelector(search.dataset.searchApply==="collection"?"#collection-search":"#deck-search");if(search.dataset.searchApply==="collection")collectionSearch=input?.value||"";else deckSearch=input?.value||"";render();});
document.addEventListener("click",e=>{const add=e.target?.closest?.("[data-add-card]");if(!add)return;const card=cardById[add.dataset.addCard],counts=deckCounts(profile.deck);if(card&&isVmaxCard(card)&&counts.vmax>=(settings.vmaxLimit??2)){e.preventDefault();e.stopImmediatePropagation();notify(`VMAX 카드는 ${settings.vmaxLimit??2}장까지입니다.`);return;}if(card?.rarity==="SSR"&&counts.ssr>=(settings.ssrLimit??2)){e.preventDefault();e.stopImmediatePropagation();notify(`SSR 카드는 ${settings.ssrLimit??2}장까지입니다.`);}},true);
document.addEventListener("click",e=>{if(e.target?.id==="reset-deck"){e.stopImmediatePropagation();profile.deck=[...STARTER_DECK].filter(id=>cardById[id]&&(profile.collection[id]||0)>0);save();render();notify("기본 덱을 복원했습니다.");}},true);
document.addEventListener("click",e=>{if(e.target?.closest?.("#top-toggle-music,#toggle-music")){unlockAudio();setAudioPref("music",!audioPrefs.music);if(e.target.closest("#toggle-music"))openGameSettings();render();return;}if(e.target?.closest?.("#top-toggle-effects,#toggle-effects")){setAudioPref("effects",!audioPrefs.effects);if(e.target.closest("#toggle-effects"))openGameSettings();render();return;}if(e.target?.closest?.("#game-settings")){openGameSettings();return;}});
document.addEventListener("click",e=>{const routeButton=e.target?.closest?.("#modal-root [data-route]");if(routeButton){modalRoot.innerHTML="";go(routeButton.dataset.route);return;}if(e.target?.closest?.("#open-profile,[data-profile]")){openProfile();return;}const start=e.target?.closest?.("[data-start-ai]");if(start){startGame(start.dataset.startAi);return;}});
document.addEventListener("click",e=>{const target=e.target;if(!(target instanceof Element))return;const settings=document.querySelector("#open-settings"),notificationsButton=document.querySelector("#open-notifications");if(settings&&(target===settings||settings.contains(target))){e.preventDefault();e.stopImmediatePropagation();openGameSettings();return;}if(notificationsButton&&(target===notificationsButton||notificationsButton.contains(target))){e.preventDefault();e.stopImmediatePropagation();openNotifications();return;}const theme=target.closest("#modal-root [data-theme]");if(theme){e.preventDefault();e.stopImmediatePropagation();uiPrefs.theme=theme.dataset.theme;saveUiPrefs();applyUiPrefs();render();openGameSettings();return;}if(target.closest("#modal-root #toggle-reduced-motion")){e.preventDefault();e.stopImmediatePropagation();uiPrefs.reducedMotion=!uiPrefs.reducedMotion;saveUiPrefs();applyUiPrefs();render();openGameSettings();return;}if(target.closest("#modal-root #toggle-compact-cards")){e.preventDefault();e.stopImmediatePropagation();uiPrefs.compactCards=!uiPrefs.compactCards;saveUiPrefs();applyUiPrefs();render();openGameSettings();return;}},true);
document.addEventListener("click",e=>{if(e.target?.id!=="confirm-reset-profile")return;e.preventDefault();e.stopImmediatePropagation();profile=resetProfile();game=null;modalRoot.innerHTML="";render();notify("초기화 완료: 기본 재화 250P 지급");},{capture:true});
document.addEventListener("keydown",e=>{if(e.key!=="Escape")return;const settingsModal=document.querySelector("#modal-root .settings-panel-rich");if(settingsModal){e.preventDefault();modalRoot.innerHTML="";}});
document.addEventListener("input",e=>{if(e.target?.id!=="music-volume")return;audioPrefs.volume=Number(e.target.value);saveAudioPrefs();const value=document.querySelector("#volume-value");if(value)value.textContent=`${audioPrefs.volume}%`;if(currentMusicKey){const track=musicTracks[currentMusicKey];if(track)track.volume=musicTargetVolume(currentMusicKey);}});
document.addEventListener("pointerdown",()=>{unlockAudio();syncRouteMusic();},{once:true});
document.addEventListener("focusin",event=>{const input=event.target;if(input?.matches?.("#simple-signin-form [name=username]"))input.removeAttribute("pattern");});
document.addEventListener("submit",async event=>{const form=event.target;if(!form?.matches?.("#simple-signin-form,#simple-signup-form"))return;event.preventDefault();event.stopPropagation();const value=new FormData(form),username=String(value.get("username")||"").trim(),password=String(value.get("password")||"");try{const email=accountEmail(username);if(form.id==="simple-signup-form"){const result=await window.politimonBackend.signUp(email,password,username);authSession=result.session||null;if(result.needsEmailConfirmation)throw new Error("Supabase에서 이메일 인증 끄기 설정이 아직 적용되지 않았습니다.");await syncDeveloperAccess();notify("계정을 만들고 로그인했습니다.");}else{const result=await window.politimonBackend.signIn(email,password);authSession=result?.user?{user:result.user}:result;await syncDeveloperAccess();notify("로그인했습니다.");}render();}catch(error){notify(`계정을 처리하지 못했습니다: ${error.message}`);}},true);
document.addEventListener("click",async event=>{const button=event.target?.closest?.("#delete-account");if(!button)return;event.preventDefault();event.stopPropagation();if(!confirm("회원 탈퇴를 진행할까요? 계정과 작성한 글을 되돌릴 수 없습니다."))return;try{await window.politimonBackend.deleteAccount();authSession=null;isDeveloper=false;activeRoom=null;galleryPosts=[];galleryLoaded=false;go("home");notify("회원 탈퇴가 완료되었습니다.");}catch(error){notify(`회원 탈퇴를 완료하지 못했습니다: ${error.message}`);}},true);
document.addEventListener("click",async event=>{const button=event.target?.closest?.("#room-ready");if(!button)return;event.preventDefault();event.stopImmediatePropagation();try{if(!validDeck(profile.deck))throw new Error(deckLimitMessage());activeRoom=await registerRoomDeck(activeRoom);activeRoom=await window.politimonBackend.setReady(activeRoom.id,!activeRoom.members.find(member=>member.user_id===currentUser().id)?.ready);watchPvpRoom(activeRoom.id);render();}catch(error){notify(`준비 상태를 바꾸지 못했습니다: ${error.message}`);}},true);
document.addEventListener("click",async event=>{const button=event.target?.closest?.("#room-start");if(!button)return;event.preventDefault();event.stopImmediatePropagation();try{if(!validDeck(profile.deck))throw new Error(deckLimitMessage());activeRoom=await registerRoomDeck(activeRoom);activeRoom=await window.politimonBackend.startRoom(activeRoom.id);await startPvpMatch();}catch(error){notify(`PvP를 시작하지 못했습니다: ${error.message}`);}},true);
document.addEventListener("click",event=>{const button=event.target?.closest?.("#refresh-active-room");if(!button)return;event.preventDefault();event.stopPropagation();refreshActiveRoom();},true);
document.addEventListener("click",async event=>{const button=event.target?.closest?.("[data-delete-gallery-post]");if(!button)return;event.preventDefault();event.stopPropagation();if(!confirm("이 글을 삭제할까요? 이 작업은 되돌릴 수 없습니다."))return;try{await window.politimonBackend.deletePost(button.dataset.deleteGalleryPost);galleryPosts=galleryPosts.filter(post=>post.id!==button.dataset.deleteGalleryPost);selectedGalleryPostId=galleryPosts[0]?.id||null;render();notify("갤러리 글을 삭제했습니다.");}catch(error){notify(`글을 삭제하지 못했습니다: ${error.message}`);}},true);
document.addEventListener("click",event=>{const leave=event.target?.closest?.("#leave-room");if(!leave)return;event.preventDefault();event.stopPropagation();leaveActiveRoom();},true);
window.addEventListener("hashchange",()=>{const next=location.hash.slice(1)||"home";if(roomNavigationLocked()&&next!=="game"&&next!=="multiplayer"){location.hash=route;notify("방에 참가 중입니다. 나가려면 방 나가기 버튼을 사용하세요.");return;}if(route==="game"&&next!=="game"){const shouldLeaveFinishedRoom=isPvpMatch()&&game?.snapshot?.().phase==="finished"&&!!activeRoom;clearBattleEffects();if(shouldLeaveFinishedRoom)leaveActiveRoom();game=null;stopPvpWatch();}if(route==="multiplayer"&&next!=="multiplayer"&&activeRoom)leaveActiveRoom();if(next==="gallery"&&route!=="gallery")galleryLoaded=false;route=next;render();});checkAchievements();save();render();window.politimonBackend?.getSession().then(async session=>{authSession=session;await syncDeveloperAccess();updateHeaderUser();if(route==="auth"||route==="home")render();}).catch(()=>{});

